import glob, re, html
pats=[]
lex_of=[]
for f in glob.glob("/tmp/xmldir2/*.xml"):
    txt=open(f, encoding='utf-8').read()
    for m in re.finditer(r'pattern="([^"]*)"', txt):
        pats.append(html.unescape(m.group(1)))

def strip_trivial(p):
    # remove leading lookbehind / lookahead assertions and trailing lookahead assertions repeatedly
    changed=True
    while changed:
        changed=False
        # find leading (?<!...) (?<=...) (?=...) (?!...) with balanced parens
        if p.startswith(('(?<!','(?<=','(?=','(?!')):
            i=0; depth=0
            # parse group
            for i,ch in enumerate(p):
                if ch=='(':
                    depth+=1
                elif ch==')':
                    depth-=1
                    if depth==0:
                        break
            p=p[i+1:]; changed=True; continue
        # trailing - need find group at end, hard approximate: if p ends with ) and contains '(?=' etc that group spans to end
        m=re.search(r'\(\?<?[=!][^()]*\)$',p)
        if m:
            p=p[:m.start()]; changed=True; continue
    return p

remaining=0
examples=[]
for p in pats:
    q=strip_trivial(p)
    bad = ('(?=' in q or '(?!' in q or '(?<=' in q or '(?<!' in q or bool(re.search(r'\\[1-9]',q)))
    if bad:
        remaining+=1
        if len(examples)<20: examples.append(p)
print("remaining bad after trivial strip", remaining)
print(examples)
