import os, re, glob, json, html, sys
import xml.etree.ElementTree as ET

SRC="/tmp/xmldir2"

def fix_duplicates(xml_text):
    # Merge duplicate attributes in a tag into space-separated single attribute
    # Find tags: <tag ...> where attrs may duplicate; need tolerant scan respecting quotes
    out=[]
    i=0
    n=len(xml_text)
    while i<n:
        if xml_text[i]=='<':
            # find end > respecting quotes
            j=i+1
            inq=None
            while j<n:
                c=xml_text[j]
                if inq:
                    if c==inq: inq=None
                elif c in ('"',"'"):
                    inq=c
                elif c=='>':
                    break
                j+=1
            tag=xml_text[i:j+1]
            # parse tag
            m=re.match(r'<\s*(/?)\s*([A-Za-z_][\w.-]*)(.*?)(\/?)>', tag, re.S)
            if m and not tag.startswith('<?') and not tag.startswith('<!'):
                prefix, name, attrstr, selfclose = m.groups()
                # parse attrs
                attrs=[]
                # attr regex
                for am in re.finditer(r'([\w.-]+)\s*=\s*"([^"]*)"', attrstr):
                    attrs.append((am.group(1), am.group(2)))
                # also single quotes? xml uses double
                if attrs:
                    # merge duplicates
                    seen={}
                    order=[]
                    for k,v in attrs:
                        if k in seen:
                            seen[k]=seen[k]+" "+v
                        else:
                            seen[k]=v; order.append(k)
                    if len(order)!=len(attrs):
                        newattr=''.join(f' {k}="{seen[k]}"' for k in order)
                        tag=f'<{prefix}{name}{newattr}{"/" if selfclose else ""}>'
            out.append(tag)
            i=j+1
        else:
            out.append(xml_text[i]); i+=1
    return ''.join(out)

def parse_rule(rule_el):
    pattern=rule_el.get("pattern") # None if absent
    emitter=None
    mutators=[]
    # include is special
    include_state=None
    for child in rule_el:
        tag=child.tag
        if tag=="token":
            emitter=["t", child.get("type")]
        elif tag=="bygroups":
            groups=[]
            for g in child:
                if g.tag=="token":
                    groups.append(["t", g.get("type")])
                elif g.tag=="using":
                    groups.append(["u", g.get("lexer")])
                elif g.tag=="usingself":
                    groups.append(["s", g.get("state")])
                elif g.tag=="usingbygroup":
                    groups.append(["ubg"]) # not expected
                else:
                    groups.append([g.tag])
            emitter=["b", groups]
        elif tag=="using":
            emitter=["u", child.get("lexer")]
        elif tag=="usingself":
            emitter=["s", child.get("state")]
        elif tag=="usingbygroup":
            # parse sub elements
            sub=None; code=None; emitters=[]
            for subel in child:
                if subel.tag=="sublexer_name_group": sub=int(subel.text.strip())
                elif subel.tag=="code_group": code=int(subel.text.strip())
                elif subel.tag=="emitters":
                    for t in subel:
                        if t.tag=="token": emitters.append(t.get("type"))
            emitter=["ubg", sub, code, emitters]
        elif tag=="push":
            states=child.get("state","").split()
            mutators.append(["push", states])
        elif tag=="pop":
            mutators.append(["pop", int(child.get("depth","1"))])
        elif tag=="combined":
            states=child.get("state","").split()
            mutators.append(["combined", states])
        elif tag=="include":
            include_state=child.get("state")
        elif tag=="mutators":
            for mchild in child:
                if mchild.tag=="push":
                    mutators.append(["push", mchild.get("state","").split()])
                elif mchild.tag=="pop":
                    mutators.append(["pop", int(mchild.get("depth","1"))])
                elif mchild.tag=="combined":
                    mutators.append(["combined", mchild.get("state","").split()])
                else:
                    print("unknown mutator", mchild.tag)
        else:
            print("unknown rule child", tag)
    if include_state is not None:
        return ["i", include_state]
    # rule representation: [pattern or None, emitter, mutators]
    return [pattern, emitter, mutators]

lexers=[]
for path in sorted(glob.glob(os.path.join(SRC,"*.xml"))):
    txt=open(path, encoding="utf-8").read()
    fixed=fix_duplicates(txt)
    try:
        root=ET.fromstring(fixed)
    except Exception as e:
        print("parse fail", path, e); continue
    cfg_el=root.find("config")
    cfg={}
    name=None; aliases=[]; filenames=[]; mimes=[]
    flags={}
    analyse=None
    priority=None
    for el in cfg_el:
        if el.tag=="name": name=el.text
        elif el.tag=="alias": aliases.append(el.text)
        elif el.tag=="filename": filenames.append(el.text)
        elif el.tag=="mime_type": mimes.append(el.text)
        elif el.tag=="analyse":
            first=el.get("first")=="true"
            regs=[]
            for r in el:
                if r.tag=="regex": regs.append([r.get("pattern"), float(r.get("score"))])
            analyse={"first": first, "regex": regs}
        elif el.tag=="priority":
            priority=float(el.text)
        else:
            flags[el.tag]= (el.text=="true")
    states={}
    rules_el=root.find("rules")
    for st in rules_el:
        if st.tag!="state": continue
        sname=st.get("name")
        rules=[]
        for r in st:
            if r.tag!="rule": 
                print("state child",r.tag); continue
            rules.append(parse_rule(r))
        states[sname]=rules
    lex={"name":name,"aliases":aliases,"filenames":filenames,"mimetypes":mimes,"flags":flags,"states":states}
    if priority is not None: lex["priority"]=priority
    if analyse: lex["analyse"]=analyse
    lexers.append(lex)

