print(f"lexers parsed {len(lexers)}")

# dump order from /tmp/order.txt
seq=[]
ordertxt=open("/tmp/order.txt").read().splitlines()
# map filename to name using file list name mapping? We use lexers list filename slug mapping reversed?
slug2name={}
def slug(name):
    s=name.lower()
    s=re.sub(r'[^a-z0-9+#-]+','_',s)
    return s
for l in lexers:
    slug2name[slug(l["name"])]=l["name"]
for line in ordertxt:
    if "already exists" in line:
        fn=line.split("/")[-1].replace(".xml already exists","")
        if fn in slug2name: seq.append(slug2name[fn])
        else: print("slug no map",fn)
    else:
        m=re.search(r'warning: "([^"]+)"',line)
        if m: seq.append("!"+m.group(1))
        else: print("order line?",line)
print("seq len",len(seq), seq[:10])

out={"lexers":lexers, "dump_order":seq}
with open("/tmp/lexers_data.json","w") as f:
    json.dump(out,f,separators=(',',':'),ensure_ascii=False)
print("size",os.path.getsize("/tmp/lexers_data.json"))
PY
