package main

import (
	"fmt"
	"strconv"
	"strings"
)

type Colour struct {
	Set bool
	R   uint8
	G   uint8
	B   uint8
	// raw numeric value for formats like #%06x (may exceed 0xffffff for weird inputs)
	raw uint32
	hasRaw bool
}

func parseColour(s string) (Colour, error) {
	// s includes leading #
	if !strings.HasPrefix(s, "#") {
		return Colour{}, fmt.Errorf("invalid colour %q", s)
	}
	v, err := strconv.ParseUint(s[1:], 16, 64)
	if err != nil {
		return Colour{}, fmt.Errorf("invalid colour %q", s)
	}
	c := Colour{Set: true, raw: uint32(v), hasRaw: true}
	c.R = uint8((v >> 16) & 0xff)
	c.G = uint8((v >> 8) & 0xff)
	c.B = uint8(v & 0xff)
	// For 3-digit etc, Go colour parsing in original: value is direct numeric,
	// e.g. #f00 => 0x000f00? Wait earlier test: #f00 gave #ff0000 in CSS.
	// That implies parsing expands? Let's examine: #f00 in CSS became #ff0000.
	// That means parser treats hex as... Actually original colour Parse: if len==4 (incl #?) i.e. 3 digits, expands each.
	// Similarly #12345 gave #012345 (that's 5 digits, treated as numeric 0x012345)
	// So only 3-digit case is special expansion.
	if len(s) == 4 {
		// expand each nibble
		r := (v >> 8) & 0xf
		g := (v >> 4) & 0xf
		b := v & 0xf
		c.R = uint8(r<<4 | r)
		c.G = uint8(g<<4 | g)
		c.B = uint8(b<<4 | b)
		c.raw = uint32(c.R)<<16 | uint32(c.G)<<8 | uint32(c.B)
	}
	return c, nil
}

func colourFromRGB(r, g, b int) Colour {
	if r < 0 { r = 0 }
	if g < 0 { g = 0 }
	if b < 0 { b = 0 }
	if r > 255 { r = 255 }
	if g > 255 { g = 255 }
	if b > 255 { b = 255 }
	return Colour{Set: true, R: uint8(r), G: uint8(g), B: uint8(b), raw: uint32(r)<<16 | uint32(g)<<8 | uint32(b), hasRaw: true}
}

func (c Colour) String() string {
	// For inline styles: short form if possible
	if !c.Set {
		return ""
	}
	full := c.hex6()
	// if each byte is doubled digit, compress
	if len(full) == 7 {
		if full[1] == full[2] && full[3] == full[4] && full[5] == full[6] {
			return "#" + string([]byte{full[1], full[3], full[5]})
		}
	}
	return full
}
func (c Colour) hex6() string {
	if c.hasRaw && c.raw > 0xffffff {
		// CSS uses #%06x of raw
		return fmt.Sprintf("#%06x", c.raw)
	}
	return fmt.Sprintf("#%02x%02x%02x", c.R, c.G, c.B)
}
func (c Colour) IsDark() bool {
	// average of channels, <0.5
	return (float64(c.R)+float64(c.G)+float64(c.B))/3.0/255.0 < 0.5
}
func mixColour(a, b Colour, frac float64) Colour {
	r := int(float64(a.R)*(1-frac) + float64(b.R)*frac)
	g := int(float64(a.G)*(1-frac) + float64(b.G)*frac)
	bl := int(float64(a.B)*(1-frac) + float64(b.B)*frac)
	return colourFromRGB(r, g, bl)
}
var whiteColour = Colour{Set: true, R: 255, G: 255, B: 255, raw: 0xffffff, hasRaw: true}
var blackColour = Colour{Set: true, R: 0, G: 0, B: 0, raw: 0, hasRaw: true}
EOF
cat colour.go | head -n 5"}

