	switch tt {
	case TTBackground, TTPreWrapper, TTLineLink, TTLineTableTD, TTLineTable, TTLineHighlight, TTLineNumbersTable, TTLineNumbers, TTLine, TTCodeLine:
		return true
	}
	return false
}
