package main

import (
	"fmt"
	"strings"
)

type Tri int

const (
	TriUnset Tri = 0
	TriYes   Tri = 1
	TriNo    Tri = -1
)

type StyleEntry struct {
	Colour     Colour
	Background Colour
	Border     Colour
	Bold       Tri
	Italic     Tri
	Underline  Tri
	NoInherit  bool
}

func (e StyleEntry) css() string {
	var parts []string
	if e.Colour.Set {
		parts = append(parts, "color: "+e.Colour.hex6())
	}
	if e.Background.Set {
		parts = append(parts, "background-color: "+e.Background.hex6())
	}
	if e.Bold == TriYes {
		parts = append(parts, "font-weight: bold")
	}
	if e.Italic == TriYes {
		parts = append(parts, "font-style: italic")
	}
	if e.Underline == TriYes {
		parts = append(parts, "text-decoration: underline")
	}
	return strings.Join(parts, "; ")
}
func (e StyleEntry) inlineCSS() string {
	var parts []string
	if e.Colour.Set {
		parts = append(parts, "color:"+e.Colour.String())
	}
	if e.Background.Set {
		parts = append(parts, "background-color:"+e.Background.String())
	}
	if e.Bold == TriYes {
		parts = append(parts, "font-weight:bold")
	}
	if e.Italic == TriYes {
		parts = append(parts, "font-style:italic")
	}
	if e.Underline == TriYes {
		parts = append(parts, "text-decoration:underline")
	}
	if len(parts) == 0 {
		return ""
	}
	return strings.Join(parts, ";") + ";"
}

func parseStyleEntry(s string) (StyleEntry, error) {
	var e StyleEntry
	s = strings.TrimSpace(s)
	if s == "" {
		return e, nil
	}
	for _, elem := range strings.Fields(s) {
		switch {
		case elem == "bold":
			e.Bold = TriYes
		case elem == "nobold":
			e.Bold = TriNo
		case elem == "italic":
			e.Italic = TriYes
		case elem == "noitalic":
			e.Italic = TriNo
		case elem == "underline":
			e.Underline = TriYes
		case elem == "nounderline":
			e.Underline = TriNo
		case elem == "noinherit":
			e.NoInherit = true
		case elem == "inherit":
			e.NoInherit = false
		case strings.HasPrefix(elem, "bg:"):
			c, err := parseColour(elem[3:])
			if err != nil {
				return e, err
			}
			e.Background = c
		case strings.HasPrefix(elem, "border:"):
			c, err := parseColour(elem[7:])
			if err != nil {
				return e, err
			}
			e.Border = c
		case strings.HasPrefix(elem, "#"):
			c, err := parseColour(elem)
			if err != nil {
				return e, err
			}
			e.Colour = c
		default:
			return e, fmt.Errorf("unknown style element %q", elem)
		}
	}
	return e, nil
}

type rawCSSLine struct {
	Type     string
	Selector string
	Body     string
}

type Style struct {
	Name    string
	direct  map[TT]StyleEntry
	synth   map[TT]StyleEntry
	cssSet  map[TT]bool
	rawCSS  []rawCSSLine
