func (s *Style) BackgroundEntry() StyleEntry {
	if e, ok := s.direct[TTBackground]; ok {
		return e
	}
	if e, ok := s.synth[TTBackground]; ok {
		return e
	}
	return StyleEntry{}
}

func mergeEntry(base, over StyleEntry) StyleEntry {
	res := base
	if over.Colour.Set {
		res.Colour = over.Colour
	}
	if over.Background.Set {
		res.Background = over.Background
	}
	if over.Border.Set {
		res.Border = over.Border
	}
	if over.Bold != TriUnset {
		res.Bold = over.Bold
	}
	if over.Italic != TriUnset {
		res.Italic = over.Italic
	}
	if over.Underline != TriUnset {
		res.Underline = over.Underline
	}
	if over.NoInherit {
		res.NoInherit = true
	}
	return res
}

// Get: fallback chain for rendering (terminal, svg, etc)
func (s *Style) Get(t TT) StyleEntry {
	if s == nil {
		return StyleEntry{}
	}
	if t == TTBackground {
		if e, ok := s.direct[TTBackground]; ok {
			return e
		}
		if e, ok := s.direct[TTText]; ok {
			return e
		}
