		}
	} else {
		st.synth[TTLineNumbersTable] = defaultLN
	}
	// ensure specials present in synth with zero if not set (for Line etc Get fallback would give background, but synth should be zero/text-derived)
	for _, tt := range []TT{TTLineLink, TTLineTableTD, TTLineTable, TTLine} {
		if _, ok := st.synth[tt]; !ok {
			st.synth[tt] = StyleEntry{}
		}
	}

	// cssSet
	for _, tt := range []TT{TTBackground, TTPreWrapper, TTLineLink, TTLineTableTD, TTLineTable, TTLineHighlight, TTLineNumbersTable, TTLineNumbers, TTLine} {
		st.cssSet[tt] = true
	}
	for tt, e := range st.synth {
		if isStandardCSS(tt) {
			if e.css() != "" {
				// check if tt was expanded (in synth via starts) or is direct/special handled above
				// synth map includes only expanded + specials, so ok
				st.cssSet[tt] = true
			}
		}
	}
	return st, nil
