	Styles map[string][][3]string         `json:"styles"`
}

var builtinStyles map[string]*Style
var builtinStyleOrder []string // list output order includes swapoff; handled separately
var termColourMap map[string]map[string]string

func initStyles() {
	var sf stylesFile
	if err := json.Unmarshal(stylesDataJSON, &sf); err != nil {
		panic(err)
	}
	builtinStyles = map[string]*Style{}
	builtinStyleOrder = sf.Order
	for name, lines := range sf.Styles {
		direct := map[TT]StyleEntry{}
		var raw []rawCSSLine
		for _, arr := range lines {
			typ, sel, body := arr[0], arr[1], arr[2]
			raw = append(raw, rawCSSLine{Type: typ, Selector: sel, Body: body})
			entry := parseCSSForType(typ, body)
			// only add meaningful entries to direct
			switch TT(typ) {
			case TTBackground:
				direct[TTBackground] = entry
			case TTPreWrapper:
				// ignore (same as background)
			case TTLineHighlight:
				direct[TTLineHighlight] = entry
			case TTLineNumbers:
				direct[TTLineNumbers] = entry
			case TTLineNumbersTable:
				direct[TTLineNumbersTable] = entry
			case TTLineLink, TTLineTableTD, TTLineTable, TTLine:
				// static only, no entry
			default:
				direct[TT(typ)] = entry
			}
		}
		st, err := buildStyle(name, direct)
		if err != nil {
			panic(err)
		}
		st.rawCSS = raw
		builtinStyles[name] = st
	}
	// term colours
	termColourMap = map[string]map[string]string{}
	_ = json.Unmarshal(termColoursJSON, &termColourMap)
}

func parseCSSDeclarations(css string) StyleEntry {
	var e StyleEntry
	css = strings.TrimSpace(css)
	css = strings.TrimSuffix(css, ";")
	for _, part := range strings.Split(css, ";") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		kv := strings.SplitN(part, ":", 2)
		if len(kv) != 2 {
			continue
		}
		key := strings.TrimSpace(kv[0])
		val := strings.TrimSpace(kv[1])
		switch key {
		case "color":
			if c, err := parseColour(val); err == nil {
				e.Colour = c
			}
		case "background-color":
			if c, err := parseColour(val); err == nil {
				e.Background = c
			}
		case "font-weight":
			if val == "bold" {
				e.Bold = TriYes
			}
		case "font-style":
			if val == "italic" {
				e.Italic = TriYes
			}
		case "text-decoration":
			if val == "underline" {
				e.Underline = TriYes
			}
		}
	}
	return e
}

func parseCSSForType(typ, body string) StyleEntry {
	body = strings.TrimSpace(body)
	switch typ {
	case "Background":
		return parseCSSDeclarations(body)
	case "PreWrapper":
		return parseCSSDeclarations(body)
	case "LineHighlight":
		return parseCSSDeclarations(body)
	case "LineNumbers", "LineNumbersTable":
		idx := strings.LastIndex(body, "0.4em;")
		if idx >= 0 {
			rest := body[idx+len("0.4em;"):]
			return parseCSSDeclarations(rest)
		}
		return StyleEntry{}
	case "LineLink", "LineTableTD", "LineTable", "Line":
		return StyleEntry{}
	default:
		return parseCSSDeclarations(body)
	}
}

func getBuiltinStyle(name string) *Style {
	lower := strings.ToLower(name)
	if lower == "swapoff" {
		return nil
	}
	if st, ok := builtinStyles[lower]; ok {
		// Return a copy? Styles are read-only except CloneWith creates new.
		return st
	}
	return nil
}
