// Compile expanded rules for a state, with include expansion.
func (ld *LexerDef) compile() {
	ld.once.Do(func() {
		ld.compiled = map[string][]CompiledRule{}
		for stateName := range ld.States {
			expanded := ld.expandState(stateName, map[string]bool{})
			var crs []CompiledRule
			for i, r := range expanded {
				cr := CompiledRule{Rule: r, Index: i}
				pat := ""
				if r.Pattern != nil {
					pat = *r.Pattern
				}
				cr.PatternStr = pat
				// compile regex
				re, useCustom, err := compilePattern(pat, ld.Flags)
				if err != nil {
					// fallback: use custom or strip
					cr.Re = re
					cr.UseCustom = useCustom
					if re == nil && !useCustom {
						// create a never-matching regex?
						cr.Re, _ = regexp.Compile(`\A[^\x00-\U0010FFFF]`)
					}
				} else {
					cr.Re = re
					cr.UseCustom = useCustom
				}
				crs = append(crs, cr)
			}
			ld.compiled[stateName] = crs
		}
