	})
}

func (ld *LexerDef) expandState(stateName string, visiting map[string]bool) []Rule {
	if visiting[stateName] {
		return nil
	}
	visiting[stateName] = true
	defer delete(visiting, stateName)
	rules, ok := ld.States[stateName]
	if !ok {
		return nil
	}
	var out []Rule
	for _, r := range rules {
		if r.Include != "" {
			sub := ld.expandState(r.Include, visiting)
			out = append(out, sub...)
		} else {
			out = append(out, r)
		}
	}
	return out
}

func compilePattern(pat string, flags map[string]bool) (*regexp.Regexp, bool, error) {
	// Build Go regex with flags
	// Determine if pattern is Go-incompatible
	if needsCustomRegex(pat) {
		// try trivial transform first
		if re, err := tryTrivialTransform(pat, flags); err == nil {
			return re, false, nil
		}
		return nil, true, nil
	}
	reStr := wrapPattern(pat, flags)
	re, err := regexp.Compile(reStr)
	if err != nil {
		// try trivial/custom
		if re2, err2 := tryTrivialTransform(pat, flags); err2 == nil {
			return re2, false, nil
		}
		return nil, true, err
	}
	return re, false, nil
}

func wrapPattern(pat string, flags map[string]bool) string {
	var fl string
	if !flags["not_multiline"] {
		fl += "m"
	}
	if flags["dot_all"] {
		fl += "s"
	}
	if flags["case_insensitive"] {
		fl += "i"
	}
	if fl == "" {
		return "(?:" + pat + ")"
	}
	return "(?" + fl + ")(?:" + pat + ")"
}

func needsCustomRegex(pat string) bool {
	if strings.Contains(pat, "(?=") || strings.Contains(pat, "(?!") || strings.Contains(pat, "(?<=") || strings.Contains(pat, "(?<!") {
		return true
	}
	// backreference \1-\9 (but not \\)
	for i := 0; i < len(pat)-1; i++ {
		if pat[i] == '\\' {
			if i+1 < len(pat) && pat[i+1] >= '1' && pat[i+1] <= '9' {
				return true
			}
			i++
		}
	}
	// possessive quantifiers *+ ++ ?+ }+ (rough)
	if strings.Contains(pat, "*+") || strings.Contains(pat, "++") || strings.Contains(pat, "?+") {
		return true
	}
	// named group (?<name> not lookbehind
	if strings.Contains(pat, "(?<") && !strings.Contains(pat, "(?<=") && !strings.Contains(pat, "(?<!") {
		return true
	}
	return false
}

var _ = fmt.Sprintf
EOF
