			depth++
		} else if c == ')' {
			depth--
			if depth == 0 {
				return i
			}
		}
	}
	return -1
}

func removeLookAssertions(pat string) string {
	var out strings.Builder
	i := 0
	for i < len(pat) {
		if i+2 < len(pat) && pat[i] == '(' && pat[i+1] == '?' {
			// check lookahead/behind
			if pat[i+2] == '=' || pat[i+2] == '!' {
