func genericCLikeStates(keywords, types []string, lineComment, blockComment bool) map[string][]Rule {
	kw := strings.Join(keywords, "|")
	tp := strings.Join(types, "|")
	rules := []Rule{
		mkRule(`\s+`, "Text"),
	}
	if lineComment {
		rules = append(rules, mkRule(`//[^\n]*`, "CommentSingle"))
