		existing[ld.Name] = true
	}
	for _, c := range cfgs {
		if existing[c.name] {
			continue
		}
		ld := &LexerDef{
			Name: c.name, Aliases: c.aliases, Filenames: c.filenames, Mimetypes: c.mimes,
			Flags: map[string]bool{},
		}
		switch c.name {
		case "Go":
