		case "Haxe":
			ld.States = genericCLikeStates([]string{"abstract","break","case","cast","catch","class","continue","default","do","dynamic","else","enum","extends","extern","false","final","for","function","if","implements","import","in","inline","interface","macro","new","null","override","package","private","public","return","static","super","switch","this","throw","true","try","typedef","untyped","using","var","while"}, []string{"Int","Float","Bool","String","Dynamic","Void","Array"}, true, true)
		case "HTTP":
			ld.States = httpStates()
		case "Raku":
			ld.States = genericCLikeStates([]string{"my","our","has","class","role","grammar","method","sub","multi","proto","only","state","let","temp","if","elsif","else","unless","while","until","for","given","when","default","loop","repeat","return","last","next","redo","fail","die","say","print"}, []string{}, true, true)
		case "reStructuredText":
			ld.States = map[string][]Rule{"root": {
				mkRule(`(?s)\.\. [^\n]*`, "Comment"),
				mkRule(`[^\n]+`, "Text"),
				mkRule(`\n`, "Text"),
			}}
		case "ERB", "PHTML", "Svelte", "Go HTML Template":
			// clone HTML states if available
			if htmlLd, ok := findLexerByCanonicalName("HTML"); ok {
				ld.States = htmlLd.States
				ld.Flags = htmlLd.Flags
			} else {
				ld.States = map[string][]Rule{"root": {mkRule(`(?s).+`, "Text")}}
			}
		default:
			ld.States = map[string][]Rule{"root": {mkRule(`(?s).+`, "Text")}}
		}
		lexerRegistry = append(lexerRegistry, ld)
		existing[c.name] = true
	}
}

func findLexerByCanonicalName(name string) (*LexerDef, bool) {
	for _, ld := range lexerRegistry {
		if ld.Name == name {
			return ld, true
		}
	}
	return nil, false
}
EOF
"}

