func registerMissingLexers() {
	// parse list_data for configs of missing lexers
	type cfg struct {
		name string
		aliases, filenames, mimes []string
	}
	var cfgs []cfg
	var cur *cfg
	for _, line := range strings.Split(listData, "\n") {
		if strings.HasPrefix(line, "  ") && !strings.HasPrefix(line, "    ") {
			cfgs = append(cfgs, cfg{name: strings.TrimSpace(line)})
			cur = &cfgs[len(cfgs)-1]
		} else if cur != nil && strings.HasPrefix(line, "    aliases: ") {
			cur.aliases = strings.Fields(strings.TrimPrefix(line, "    aliases: "))
		} else if cur != nil && strings.HasPrefix(line, "    filenames: ") {
			cur.filenames = strings.Fields(strings.TrimPrefix(line, "    filenames: "))
		} else if cur != nil && strings.HasPrefix(line, "    mimetypes: ") {
