// glob match using path.Match on base name
func filenameMatchesPattern(filename, pattern string) bool {
	base := filename
	// match against base name if filename contains /
	if idx := strings.LastIndex(base, "/"); idx >= 0 {
		base = base[idx+1:]
	}
	// path.Match is case sensitive
	ok, err := path.Match(pattern, base)
	if err == nil && ok {
		return true
	}
	// Some patterns may contain '/'? Then match full?
	if strings.Contains(pattern, "/") {
