			}
			if re.MatchString(text) {
				total += ap.Score
			}
		}
		if total > bestScore {
			bestScore = total
			best = ld
		} else if total == bestScore && total > 0 && best != nil {
			// tie: keep earlier? Alphabetical by name? Keep existing.
		}
	}
	if bestScore > 0 {
		return best
	}
	return nil
}

func compileAnalysePattern(pat string) (*regexp.Regexp, error) {
	// analyse patterns are not anchored in our wrapping; use as is with multiline flag
	// Some patterns start with ^ - need multiline
	reStr := "(?m)(?s:" + pat + ")"
	// DotAll may change but analyse regexes maybe expect . not newline? Use (?m) only
	reStr = "(?m)(?:" + pat + ")"
	re, err := regexp.Compile(reStr)
	if err != nil {
		// trivial removal
		p := removeLookAssertions(pat)
		return regexp.Compile("(?m)(?:" + p + ")")
	}
	return re, nil
}
