//go:embed svg_font.txt
var svgFont string

// Lines splitting
type lineTokens struct {
	Tokens []Token
	HasNL  bool
}

func splitLines(tokens []Token) []lineTokens {
	var lines []lineTokens
	var cur []Token
	for _, tok := range tokens {
		val := tok.Value
		start := 0
		for i := 0; i < len(val); i++ {
			if val[i] == '\n' {
				seg := val[start : i+1]
				cur = append(cur, Token{Type: tok.Type, Value: seg})
				lines = append(lines, lineTokens{Tokens: cur, HasNL: true})
				cur = nil
				start = i + 1
			}
		}
		if start < len(val) {
			cur = append(cur, Token{Type: tok.Type, Value: val[start:]})
		}
	}
	if len(cur) > 0 {
		lines = append(lines, lineTokens{Tokens: cur, HasNL: false})
	}
	return lines
}

// ---- noop, tokens, json ----
func formatNoop(w io.Writer, tokens []Token) error {
	for _, t := range tokens {
		_, err := io.WriteString(w, t.Value)
		if err != nil {
			return err
		}
	}
	return nil
}
func formatTokens(w io.Writer, tokens []Token) error {
	for _, t := range tokens {
		_, err := fmt.Fprintf(w, "&Token{%s, %q}\n", string(t.Type), t.Value)
		if err != nil {
			return err
		}
	}
	return nil
}
type jsonToken struct {
	Type  string `json:"type"`
	Value string `json:"value"`
}
func formatJSON(w io.Writer, tokens []Token) error {
	if _, err := io.WriteString(w, "[\n"); err != nil {
		return err
	}
	for i, t := range tokens {
		b, _ := json.Marshal(jsonToken{Type: string(t.Type), Value: t.Value})
		// json.Marshal returns {"type":"...","value":"..."} with HTML escaping as original
		if i > 0 {
			if _, err := io.WriteString(w, ",\n"); err != nil {
				return err
			}
		} else {
			// first entry doesn't have separator, but entries are printed each on new line? Structure: "[\n  {...},\n  {...}\n]\n"
			// We handle by writing indent before each token, and separator logic below in loop restructured.
			_ = b
		}
		_ = i
		_ = b
		break
	}
	// Reimplement cleanly
	// (The above partial write already wrote "[\n")
	for i, t := range tokens {
		if i > 0 {
			if _, err := io.WriteString(w, ",\n"); err != nil {
				return err
			}
		}
