			if tabWidth != 8 {
				if typ == "Background" {
					line = applyTabToBackgroundLine(line, tabWidth)
				} else if typ == "PreWrapper" {
					line = applyTabToPreWrapperLine(line, tabWidth)
				}
			}
			if _, err := io.WriteString(w, line+"\n"); err != nil {
				return err
			}
		}
