		// But cssSet includes specials, they are in synth map (or zero)
		if tt == TTBackground {
			bg := style.Get(TTBackground)
			css := bg.css()
			body := css + ";"
			if css == "" {
				body = ";"
			}
			line := fmt.Sprintf("/* Background */ .%sbg { %s }", prefix, body)
			if tabWidth != 8 {
				line = applyTabToBackgroundLine(line, tabWidth)
			}
			if _, err := io.WriteString(w, line+"\n"); err != nil { return err }
			continue
		}
		if tt == TTPreWrapper {
			bg := style.Get(TTBackground)
			// PreWrapper synth equals background for our purposes
			css := bg.css()
			body := ""
			if css == "" {
