	for _, t := range tokens {
		_, err := fmt.Fprintf(w, "&Token{%s, %q}\n", string(t.Type), t.Value)
		if err != nil {
			return err
		}
	}
	return nil
}
type jsonToken struct {
	Type  string `json:"type"`
	Value string `json:"value"`
}
func formatJSON(w io.Writer, tokens []Token) error {
	if _, err := io.WriteString(w, "[\n"); err != nil {
		return err
	}
	for i, t := range tokens {
		b, _ := json.Marshal(jsonToken{Type: string(t.Type), Value: t.Value})
		// json.Marshal returns {"type":"...","value":"..."} with HTML escaping as original
		if i > 0 {
			if _, err := io.WriteString(w, ",\n"); err != nil {
				return err
			}
		} else {
			// first entry doesn't have separator, but entries are printed each on new line? Structure: "[\n  {...},\n  {...}\n]\n"
			// We handle by writing indent before each token, and separator logic below in loop restructured.
			_ = b
		}
		_ = i
		_ = b
