			if val[i] == '\n' {
				seg := val[start : i+1]
				cur = append(cur, Token{Type: tok.Type, Value: seg})
				lines = append(lines, lineTokens{Tokens: cur, HasNL: true})
				cur = nil
				start = i + 1
			}
		}
		if start < len(val) {
			cur = append(cur, Token{Type: tok.Type, Value: val[start:]})
		}
	}
	if len(cur) > 0 {
		lines = append(lines, lineTokens{Tokens: cur, HasNL: false})
	}
	return lines
}

