// ---- terminal ----
func colourTo256(c Colour) int {
	if m, ok := termColourMap[c.hex6()]; ok {
		if s, ok2 := m["terminal256"]; ok2 {
			// parse 38;5;N
			var n int
			fmt.Sscanf(s, "\x1b[38;5;%dm", &n)
			// sscanf with escape may not work, extract digits
			re := regexp.MustCompile(`38;5;(\d+)`)
			mm := re.FindStringSubmatch(s)
			if mm != nil {
				n, _ = strconv.Atoi(mm[1])
				return n
			}
			return n
		}
	}
	// approximation: nearest palette (cube+sys+grey)
	type pal struct { idx, r, g, b int }
	var pals []pal
	levels := []int{0, 95, 135, 175, 215, 255}
	for ri, r := range levels {
		for gi, g := range levels {
			for bi, b := range levels {
				idx := 16 + 36*ri + 6*gi + bi
				pals = append(pals, pal{idx, r, g, b})
			}
		}
	}
	sys := []string{"#000000", "#800000", "#008000", "#808000", "#000080", "#800080", "#008080", "#c0c0c0"}
	for i, hx := range sys {
		cc, _ := parseColour(hx)
		pals = append(pals, pal{i, int(cc.R), int(cc.G), int(cc.B)})
	}
	for i := 0; i < 24; i++ {
		v := 8 + i*10
		pals = append(pals, pal{232 + i, v, v, v})
	}
	best := 16
	bestD := int64(1 << 62)
	for _, p := range pals {
		dr := int64(int(c.R) - p.r)
		dg := int64(int(c.G) - p.g)
		db := int64(int(c.B) - p.b)
		d := dr*dr + dg*dg + db*db
		if d < bestD {
			bestD = d
			best = p.idx
		}
	}
	return best
}
func colourTo16(c Colour) int {
	if m, ok := termColourMap[c.hex6()]; ok {
		if s, ok2 := m["terminal16"]; ok2 {
			re := regexp.MustCompile(`\[(\d+)m`)
			mms := re.FindAllStringSubmatch(s, -1)
			if len(mms) > 0 {
				n, _ := strconv.Atoi(mms[len(mms)-1][1])
				return n
			}
		}
	}
	// approx nearest CSS palette
	palHex := []string{"#000000", "#800000", "#008000", "#808000", "#000080", "#800080", "#008080", "#c0c0c0", "#808080", "#ff0000", "#00ff00", "#ffff00", "#0000ff", "#ff00ff", "#00ffff", "#ffffff"}
	codes := []int{30, 31, 32, 33, 34, 35, 36, 37, 90, 91, 92, 93, 94, 95, 96, 97}
	best := 30
	bestD := int64(1 << 62)
	for i, hx := range palHex {
		cc, _ := parseColour(hx)
		dr := int64(int(c.R) - int(cc.R))
		dg := int64(int(c.G) - int(cc.G))
		db := int64(int(c.B) - int(cc.B))
		d := dr*dr + dg*dg + db*db
		if d < bestD {
			bestD = d
			best = codes[i]
		}
	}
	return best
}
func terminalFGSeq(variant string, c Colour) string {
	switch variant {
	case "terminal16m":
		return fmt.Sprintf("\x1b[38;2;%d;%d;%dm", c.R, c.G, c.B)
	case "terminal256":
		return fmt.Sprintf("\x1b[38;5;%dm", colourTo256(c))
	case "terminal16":
		return fmt.Sprintf("\x1b[%dm", colourTo16(c))
	default: // terminal8 / terminal
		if m, ok := termColourMap[c.hex6()]; ok {
			if s, ok2 := m["terminal8"]; ok2 {
				return s
			}
		}
		code16 := colourTo16(c)
		if code16 >= 90 {
			return fmt.Sprintf("\x1b[1m\x1b[%dm", code16-60)
		}
		return fmt.Sprintf("\x1b[%dm", code16)
	}
}
func terminalBGSeq(variant string, c Colour) string {
	switch variant {
	case "terminal16m":
		return fmt.Sprintf("\x1b[48;2;%d;%d;%dm", c.R, c.G, c.B)
	case "terminal256":
		return fmt.Sprintf("\x1b[48;5;%dm", colourTo256(c))
	case "terminal16":
		code := colourTo16(c)
		if code >= 90 {
			return fmt.Sprintf("\x1b[%dm", code+10) // 90->100
		}
		return fmt.Sprintf("\x1b[%dm", code+10)
	default:
		if m, ok := termColourMap[c.hex6()]; ok {
			if s, ok2 := m["terminal8"]; ok2 {
				// s is fg seq: either "\x1b[37m" or "\x1b[1m\x1b[37m"
				// transform last code +10
				re := regexp.MustCompile(`\[(\d+)m`)
				mms := re.FindAllStringSubmatchIndex(s, -1)
				if len(mms) > 0 {
					// reconstruct: keep prefix up to last sequence, replace code
					last := mms[len(mms)-1]
					codeStr := s[last[2]:last[3]]
					code, _ := strconv.Atoi(codeStr)
					prefix := s[:last[0]]
					return prefix + fmt.Sprintf("\x1b[%dm", code+10)
				}
				return s
			}
		}
		code16 := colourTo16(c)
		if code16 >= 90 {
			return fmt.Sprintf("\x1b[1m\x1b[%dm", code16-60+10)
		}
		return fmt.Sprintf("\x1b[%dm", code16+10)
	}
}

func formatTerminal(w io.Writer, tokens []Token, style *Style, variant string) error {
	if variant == "terminal" {
		variant = "terminal8"
	}
	lines := splitLines(tokens)
	for _, line := range lines {
		for _, tok := range line.Tokens {
			entry := style.Get(tok.Type)
			var seq strings.Builder
			if entry.Bold == TriYes {
				seq.WriteString("\x1b[1m")
			}
			if entry.Underline == TriYes {
				seq.WriteString("\x1b[4m")
			}
			if entry.Italic == TriYes {
				seq.WriteString("\x1b[3m")
			}
			if entry.Colour.Set {
				seq.WriteString(terminalFGSeq(variant, entry.Colour))
			}
			if entry.Background.Set {
				seq.WriteString(terminalBGSeq(variant, entry.Background))
			}
			text := strings.TrimSuffix(tok.Value, "\n")
			if seq.Len() == 0 {
				if _, err := io.WriteString(w, text); err != nil {
					return err
				}
			} else {
				if _, err := io.WriteString(w, seq.String()+text+"\x1b[0m"); err != nil {
					return err
				}
			}
		}
		if line.HasNL {
			if _, err := io.WriteString(w, "\n"); err != nil {
				return err
			}
		}
	}
	return nil
}

// ---- HTML helpers ----
func escapeHTML(s string) string {
	// Go html.EscapeString equivalent: < > & " ' -> &#34; &#39;
	return html.EscapeString(s)
}
func escapeXML(s string) string {
	// For SVG: & < > " -> &amp; &lt; &gt; &quot; , ' stays
	r := strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", "\"", "&quot;")
	return r.Replace(s)
}

func inlineTrailing(e StyleEntry) string {
	s := e.inlineCSS()
	if s == "" {
		return ";"
	}
	return s
}

// WriteCSS for a style with given prefix and tabWidth (normalised, 0->8)
func writeCSS(w io.Writer, style *Style, prefix string, tabWidth int, rawOverrides map[string]StyleEntry) error {
	if tabWidth == 0 {
		tabWidth = 8
	}
	if style.rawCSS != nil && rawOverrides == nil && prefix == "" && tabWidth == 8 {
		// fast path original lines (but still need prefix/tab handling below - this condition ensures none)
		for _, line := range style.rawCSS {
			if _, err := fmt.Fprintf(w, "/* %s */ %s { %s }\n", line.Type, line.Selector, line.Body); err != nil {
				return err
			}
		}
		return nil
	}
	if style.rawCSS != nil {
		for _, rawline := range style.rawCSS {
			typ := rawline.Type
			body := rawline.Body
			if rawOverrides != nil {
				if ov, ok := rawOverrides[typ]; ok {
					// regenerate body for LN/HL
					if typ == "LineNumbers" || typ == "LineNumbersTable" {
						static := "white-space: pre; -webkit-user-select: none; user-select: none; margin-right: 0.4em; padding: 0 0.4em 0 0.4em;"
						body = static + ov.css()
					} else if typ == "LineHighlight" {
						body = ov.css()
					}
				}
			}
			line := fmt.Sprintf("/* %s */ %s { %s }", typ, transformSelector(rawline.Selector, prefix), body)
			// tab handling
			if tabWidth != 8 {
				if typ == "Background" {
					line = applyTabToBackgroundLine(line, tabWidth)
				} else if typ == "PreWrapper" {
					line = applyTabToPreWrapperLine(line, tabWidth)
				}
			}
			if _, err := io.WriteString(w, line+"\n"); err != nil {
				return err
			}
		}
		return nil
	}
	// generated from synth
	for _, tt := range cssOrder {
		if !style.cssSet[tt] {
			continue
		}
		entry, _ := style.SynthGet(tt)
		// For special types, synth entry may be present; for Line etc we stored synth.
		// But cssSet includes specials, they are in synth map (or zero)
		if tt == TTBackground {
			bg := style.Get(TTBackground)
			css := bg.css()
			body := css + ";"
			if css == "" {
				body = ";"
			}
			line := fmt.Sprintf("/* Background */ .%sbg { %s }", prefix, body)
			if tabWidth != 8 {
				line = applyTabToBackgroundLine(line, tabWidth)
			}
			if _, err := io.WriteString(w, line+"\n"); err != nil { return err }
			continue
		}
		if tt == TTPreWrapper {
			bg := style.Get(TTBackground)
			// PreWrapper synth equals background for our purposes
			css := bg.css()
			body := ""
			if css == "" {
				body = "; -webkit-text-size-adjust: none;"
			} else {
				body = css + "; -webkit-text-size-adjust: none;"
			}
			line := fmt.Sprintf("/* PreWrapper */ .%schroma { %s }", prefix, body)
			if tabWidth != 8 {
				line = applyTabToPreWrapperLine(line, tabWidth)
			}
			if _, err := io.WriteString(w, line+"\n"); err != nil { return err }
			continue
		}
		// other types
		var body string
		switch tt {
		case TTLineLink:
			body = "outline: none; text-decoration: none; color: inherit" + entry.css()
		case TTLineTableTD:
			body = "vertical-align: top; padding: 0; margin: 0; border: 0;" + entry.css()
		case TTLineTable:
			body = "border-spacing: 0; padding: 0; margin: 0; border: 0;" + entry.css()
		case TTLineHighlight:
			body = entry.css()
		case TTLineNumbersTable, TTLineNumbers:
			body = "white-space: pre; -webkit-user-select: none; user-select: none; margin-right: 0.4em; padding: 0 0.4em 0 0.4em;" + entry.css()
		case TTLine:
			body = "display: flex;" + entry.css()
		default:
			body = entry.css()
		}
		selector := fmt.Sprintf(".%schroma .%s%s", prefix, prefix, tokenClass(tt))
		if tt == TTBackground {
			selector = fmt.Sprintf(".%sbg", prefix)
		}
		line := fmt.Sprintf("/* %s */ %s { %s }", string(tt), selector, body)
		if _, err := io.WriteString(w, line+"\n"); err != nil { return err }
	}
	return nil
}

func transformSelector(sel, prefix string) string {
	if prefix == "" {
		return sel
	}
	re := regexp.MustCompile(`\.([A-Za-z0-9_-]+)`)
	return re.ReplaceAllString(sel, "."+prefix+"$1")
}
func applyTabToBackgroundLine(line string, tw int) string {
	// line ends with " }"
	// replace last "; }" with ";-moz-tab-size: N; -o-tab-size: N; tab-size: N; }"
	if strings.HasSuffix(line, "; }") {
		return strings.TrimSuffix(line, "; }") + fmt.Sprintf(";-moz-tab-size: %d; -o-tab-size: %d; tab-size: %d; }", tw, tw, tw)
	}
	if strings.HasSuffix(line, " }") {
		return strings.TrimSuffix(line, " }") + fmt.Sprintf(";-moz-tab-size: %d; -o-tab-size: %d; tab-size: %d; }", tw, tw, tw)
	}
	return line
}
func applyTabToPreWrapperLine(line string, tw int) string {
	if strings.Contains(line, "; -webkit-text-size-adjust: none;") {
		return strings.Replace(line, "; -webkit-text-size-adjust: none;", fmt.Sprintf(";-moz-tab-size: %d; -o-tab-size: %d; tab-size: %d; -webkit-text-size-adjust: none;", tw, tw, tw), 1)
	}
	return line
}
