			return true
		}
	}
	return false
}
func parseRanges(s string) (rangesSet, error) {
	var rs rangesSet
	if s == "" {
		return rs, nil
	}
	for _, part := range strings.Split(s, ",") {
		pieces := strings.Split(part, ":")
		if len(pieces) == 1 {
			v, err := parseIntForRange(pieces[0], true)
			if err != nil { return rs, err }
			rs.ranges = append(rs.ranges, [2]int{v, v})
		} else if len(pieces) == 2 {
			minv, err := parseIntForRange(pieces[0], true)
			if err != nil { return rs, err }
			maxv, err := parseIntForRange(pieces[1], false)
			if err != nil { return rs, err }
