// relative inline attributes for a token (compared to background)
func inlineAttrForToken(style *Style, tok Token) (attr string, differs bool) {
	entry := style.Get(tok.Type)
	baseText := style.Get(TTText) // colour etc without bg
	bgEntry := style.Get(TTBackground)
	// differs if entry != baseText in significant fields
	if entry.Colour == baseText.Colour && entry.Background == baseText.Background && entry.Bold == baseText.Bold && entry.Italic == baseText.Italic && entry.Underline == baseText.Underline {
		// Note for bg-only token, Background fields: baseText.Background may be from Text category etc; token's background is its explicit bg, baseText's is ... Text's bg is inherited? Our Get Text drops bg from Background only, so it could be empty.
		// If entry background set and differs from bgEntry background, it should differ - but above compared to baseText.Background (which for Text may be empty). If entry bg set, entry.Background != baseText.Background (empty) so already differ.
		return "", false
	}
	var parts []string
	if entry.Colour.Set && entry.Colour != bgEntry.Colour {
		parts = append(parts, "color:"+entry.Colour.String())
	}
	if entry.Background.Set && entry.Background != bgEntry.Background {
		parts = append(parts, "background-color:"+entry.Background.String())
	}
	if entry.Bold == TriYes && bgEntry.Bold != TriYes {
		parts = append(parts, "font-weight:bold")
	}
	if entry.Italic == TriYes && bgEntry.Italic != TriYes {
		parts = append(parts, "font-style:italic")
	}
	if entry.Underline == TriYes && bgEntry.Underline != TriYes {
		parts = append(parts, "text-decoration:underline")
	}
