func preStyleInline(style *Style, tabWidth int, highlight rangesSet, hasHighlight bool) string {
	bg := style.Get(TTBackground)
	s := inlineTrailing(bg)
	if tabWidth != 8 {
		s += fmt.Sprintf("-moz-tab-size:%d;-o-tab-size:%d;tab-size:%d;", tabWidth, tabWidth, tabWidth)
