	if _, err := io.WriteString(w, "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"); err != nil { return err }
	if _, err := io.WriteString(w, "<!DOCTYPE svg PUBLIC \"-//W3C//DTD SVG 1.0//EN\" \"http://www.w3.org/TR/2001/REC-SVG-20010904/DTD/svg10.dtd\">\n"); err != nil { return err }
	if _, err := fmt.Fprintf(w, "<svg width=\"%dpx\" height=\"%dpx\" xmlns=\"http://www.w3.org/2000/svg\">\n", widthPx, heightPx); err != nil { return err }
	if _, err := io.WriteString(w, "<style>\n"); err != nil { return err }
	if _, err := io.WriteString(w, svgFont); err != nil { return err }
	bgEntry := style.Get(TTBackground)
	if _, err := fmt.Fprintf(w, "</style><rect width=\"100%%\" height=\"100%%\" fill=\"%s\"/>\n", svgColourStr(bgEntry.Background)); err != nil { return err }
	if _, err := fmt.Fprintf(w, "<g font-family=\"Liberation Mono\" font-size=\"14px\" fill=\"%s\">\n", svgColourStr(bgEntry.Colour)); err != nil { return err }
	// rects
	for lineIdx, line := range lines {
		x := 0
		for _, tok := range line.Tokens {
			entry := style.Get(tok.Type)
			textTrim := strings.TrimSuffix(tok.Value, "\n")
			expanded := expandTabs(textTrim)
			if entry.Background.Set {
				y := 0.25 + float64(lineIdx)*1.2
				id := escapeXML(expanded)
				if _, err := fmt.Fprintf(w, "<rect id=\"%s\" x=\"%dch\" y=\"%fem\" width=\"%dch\" height=\"1.2em\" fill=\"%s\" />\n", id, x, y, len(expanded), svgColourStr(entry.Background)); err != nil { return err }
			}
			x += len(expanded)
		}
	}
	// texts
	for lineIdx, line := range lines {
		y := float64(lineIdx+1) * 1.2
		if _, err := fmt.Fprintf(w, "<text x=\"0\" y=\"%fem\" xml:space=\"preserve\">", y); err != nil { return err }
		for _, tok := range line.Tokens {
			entry := style.Get(tok.Type)
			textTrim := strings.TrimSuffix(tok.Value, "\n")
			expanded := expandTabs(textTrim)
			escaped := escapeXML(expanded)
			escaped = strings.ReplaceAll(escaped, " ", "&#160;")
			// differs from global fill?
			bgCol := bgEntry.Colour
			needsSpan := false
			var attrs []string
			if entry.Colour.Set && entry.Colour != bgCol {
				attrs = append(attrs, fmt.Sprintf("fill=\"%s\"", svgColourStr(entry.Colour)))
				needsSpan = true
			}
			// if entry colour unset but bold/italic etc, needs span without fill
			if entry.Bold == TriYes {
				attrs = append(attrs, "font-weight=\"bold\"")
				needsSpan = true
			}
			if entry.Italic == TriYes {
				attrs = append(attrs, "font-style=\"italic\"")
				needsSpan = true
			}
			if entry.Underline == TriYes {
				attrs = append(attrs, "text-decoration=\"underline\"")
				needsSpan = true
			}
			if needsSpan {
				attrStr := ""
				if len(attrs) > 0 {
					attrStr = " " + strings.Join(attrs, " ")
				}
				if _, err := fmt.Fprintf(w, "<tspan%s>%s</tspan>", attrStr, escaped); err != nil { return err }
			} else {
				if _, err := io.WriteString(w, escaped); err != nil { return err }
			}
		}
		if line.HasNL {
			if _, err := io.WriteString(w, "\n"); err != nil { return err }
		}
		if _, err := io.WriteString(w, "</text>"); err != nil { return err }
	}
	if _, err := io.WriteString(w, "\n</g>\n</svg>\n"); err != nil { return err }
	return nil
}
EOF
"}

