{"command":"cat > cli.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

type FlagDef struct {
	Long  string
	Short string
	Kind  string // bool, string, int, enum, existingdir
	Placeholder string // for help error messages: "string", "int", "file"
}

var flagDefs = []FlagDef{
	{Long: "help", Short: "h", Kind: "bool"},
	{Long: "version", Kind: "bool"},
	{Long: "list", Kind: "bool"},
	{Long: "unbuffered", Kind: "bool"},
	{Long: "trace", Kind: "bool"},
	{Long: "check", Kind: "bool"},
	{Long: "filename", Kind: "string"},
	{Long: "fail", Kind: "bool"},
	{Long: "profile", Kind: "string"},
	{Long: "xml", Kind: "existingdir"},
	{Long: "lexer", Short: "l", Kind: "string"},
	{Long: "style", Short: "s", Kind: "string"},
	{Long: "formatter", Short: "f", Kind: "enum"},
	{Long: "json", Kind: "bool"},
	{Long: "html", Kind: "bool"},
	{Long: "svg", Kind: "bool"},
	{Long: "html-prefix", Kind: "string"},
	{Long: "html-styles", Kind: "bool"},
	{Long: "html-all-styles", Kind: "bool"},
	{Long: "html-only", Kind: "bool"},
	{Long: "html-inline-styles", Kind: "bool"},
	{Long: "html-tab-width", Kind: "int"},
	{Long: "html-lines", Kind: "bool"},
	{Long: "html-lines-table", Kind: "bool"},
	{Long: "html-lines-style", Kind: "string"},
	{Long: "html-highlight", Kind: "string"},
	{Long: "html-highlight-style", Kind: "string"},
	{Long: "html-base-line", Kind: "int"},
	{Long: "html-prevent-surrounding-pre", Kind: "bool"},
	{Long: "html-linkable-lines", Kind: "bool"},
}

func findLongFlag(name string) *FlagDef {
	for i := range flagDefs {
		if flagDefs[i].Long == name {
			return &flagDefs[i]
		}
	}
	return nil
}
func findShortFlag(ch rune) *FlagDef {
	s := string(ch)
	for i := range flagDefs {
		if flagDefs[i].Short == s {
			return &flagDefs[i]
		}
	}
	return nil
}

type CLI struct {
	Files      []string
	Version    bool
	Help       bool
	List       bool
	Unbuffered bool
	Trace      bool
	Check      bool
	Filename   string
	Fail       bool
	Profile    string
	XML        string
	Lexer      string
	Style      string
	Formatter  string
	JSON       bool
	HTMLFlag   bool
	SVG        bool
	HTMLPrefix string
	HTMLStyles bool
	HTMLAllStyles bool
	HTMLOnly   bool
	HTMLInlineStyles bool
	HTMLTabWidth int
	HTMLLines  bool
	HTMLLinesTable bool
	HTMLLinesStyle string
	HTMLHighlight string
	HTMLHighlightStyle string
	HTMLBaseLine int
	HTMLPreventSurroundingPre bool
	HTMLLinkableLines bool

	// appearance order of help/version
	helpVersionOrder []string
}

type parseResult struct {
	cli *CLI
	hook string // "help" or "version" or ""
	errMsg string
}

func (c *CLI) setBool(long string, v bool) {
	switch long {
	case "help": c.Help = v
	case "version": c.Version = v
	case "list": c.List = v
	case "unbuffered": c.Unbuffered = v
	case "trace": c.Trace = v
	case "check": c.Check = v
	case "fail": c.Fail = v
	case "json": c.JSON = v
	case "html": c.HTMLFlag = v
	case "svg": c.SVG = v
	case "html-styles": c.HTMLStyles = v
	case "html-all-styles": c.HTMLAllStyles = v
	case "html-only": c.HTMLOnly = v
	case "html-inline-styles": c.HTMLInlineStyles = v
	case "html-lines": c.HTMLLines = v
	case "html-lines-table": c.HTMLLinesTable = v
	case "html-prevent-surrounding-pre": c.HTMLPreventSurroundingPre = v
	case "html-linkable-lines": c.HTMLLinkableLines = v
	}
}
func (c *CLI) setString(long, v string) error {
	switch long {
	case "filename": c.Filename = v
	case "profile": c.Profile = v
	case "xml": c.XML = v
	case "lexer": c.Lexer = v
	case "style": c.Style = v
	case "formatter": c.Formatter = v
	case "html-prefix": c.HTMLPrefix = v
	case "html-lines-style": c.HTMLLinesStyle = v
	case "html-highlight": c.HTMLHighlight = v
	case "html-highlight-style": c.HTMLHighlightStyle = v
	}
	return nil
}
func (c *CLI) setInt(long string, v int64) {
	switch long {
	case "html-tab-width": c.HTMLTabWidth = int(v)
	case "html-base-line": c.HTMLBaseLine = int(v)
	}
}

func parseBoolValue(s string) (bool, bool) {
	lower := strings.ToLower(s)
	switch lower {
	case "true", "1", "yes":
		return true, true
	case "false", "0", "no":
		return false, true
	}
	return false, false
}

func levenshtein(a, b string) int {
	la := []rune(a); lb := []rune(b)
	d := make([][]int, len(la)+1)
	for i := range d {
		d[i] = make([]int, len(lb)+1)
		d[i][0] = i
	}
	for j := range d[0] { d[0][j] = j }
	for i := 1; i <= len(la); i++ {
		for j := 1; j <= len(lb); j++ {
			cost := 0
			if la[i-1] != lb[j-1] { cost = 1 }
			d[i][j] = min3(d[i-1][j]+1, d[i][j-1]+1, d[i-1][j-1]+cost)
		}
	}
	return d[len(la)][len(lb)]
}
func min3(a,b,c int) int {
	if a < b { if a < c { return a }; return c }
	if b < c { return b }; return c
}

func suggestionsForLong(input string) []string {
	var out []string
	for _, fd := range flagDefs {
		// long
		if strings.HasPrefix(fd.Long, input) || strings.HasPrefix(input, fd.Long) || levenshtein(input, fd.Long) <= 2 {
			out = append(out, "--"+fd.Long)
		}
		// short
		if fd.Short != "" {
			if levenshtein(input, fd.Short) < 2 {
				out = append(out, "-"+fd.Short)
			}
		}
	}
	return out
}
func formatUnknownLong(input string) string {
	cands := suggestionsForLong(input)
	if len(cands) == 0 {
		return fmt.Sprintf("unknown flag --%s", input)
	} else if len(cands) == 1 {
		return fmt.Sprintf("unknown flag --%s, did you mean %q?", input, cands[0])
	} else {
		var quoted []string
		for _, c := range cands { quoted = append(quoted, fmt.Sprintf("%q", c)) }
		return fmt.Sprintf("unknown flag --%s, did you mean one of %s?", input, strings.Join(quoted, ", "))
	}
}
func formatUnknownShort(ch string) string {
	return fmt.Sprintf("unknown flag -%s, did you mean one of \"-h\", \"-l\", \"-s\", \"-f\"?", ch)
}

func tokenKindDesc(arg string) string {
	if arg == "--" || strings.HasPrefix(arg, "--") {
		return "long flag"
	}
	return "short flag"
}

func parseArgs(args []string) parseResult {
	cli := &CLI{
		Lexer: "autodetect",
		Style: "swapoff",
		Formatter: "terminal",
		HTMLTabWidth: 8,
		HTMLBaseLine: 1,
	}
	// defaults for HTMLTabWidth was set; need know if user set? It's default 8 always.
	i := 0
	afterDashDash := false
	for i < len(args) {
		arg := args[i]
		i++
		if afterDashDash {
			if errMsg := addPositional(cli, arg); errMsg != "" { return parseResult{errMsg: errMsg} }
			continue
		}
		if arg == "--" {
			afterDashDash = true
			continue
		}
		if arg == "-" || !strings.HasPrefix(arg, "-") {
			if errMsg := addPositional(cli, arg); errMsg != "" { return parseResult{errMsg: errMsg} }
			continue
		}
		if strings.HasPrefix(arg, "--") {
			raw := arg[2:]
			name := raw
			var attached *string
			if idx := strings.Index(raw, "="); idx >= 0 {
				name = raw[:idx]
				v := raw[idx+1:]
				attached = &v
			}
			fd := findLongFlag(name)
			if fd == nil {
				return parseResult{errMsg: formatUnknownLong(name)}
			}
			// handle bool/string etc.
			if fd.Kind == "bool" {
				var v bool
				if attached != nil {
					b, ok := parseBoolValue(*attached)
					if !ok {
						return parseResult{errMsg: fmt.Sprintf("--%s: bool value must be true, 1, yes, false, 0 or no but got %q", fd.Long, *attached)}
					}
					v = b
				} else {
					v = true
				}
				cli.setBool(fd.Long, v)
				if fd.Long == "help" || fd.Long == "version" {
					cli.helpVersionOrder = append(cli.helpVersionOrder, fd.Long)
				}
				continue
			}
			// non-bool needs value
			var val string
			if attached != nil {
				val = *attached
			} else {
				// need next token
				if i >= len(args) {
					typeName := "string"
					if fd.Kind == "int" { typeName = "int" }
					if fd.Kind == "existingdir" { typeName = "file" }
					return parseResult{errMsg: fmt.Sprintf("--%s: expected %s value but got \"EOL\" (<EOL>)", fd.Long, typeName)}
				}
				next := args[i]
				if next != "-" && strings.HasPrefix(next, "-") && len(next) > 1 {
					kind := tokenKindDesc(next)
					typeName := "string"
					if fd.Kind == "int" { typeName = "int" }
					if fd.Kind == "existingdir" { typeName = "file" }
					return parseResult{errMsg: fmt.Sprintf("--%s: expected %s value but got %q (%s); perhaps try --%s=%q?", fd.Long, typeName, next, kind, fd.Long, next)}
				}
				val = next
				i++
			}
			// process value by kind
			if errMsg := setNonBool(cli, fd, val); errMsg != "" { return parseResult{errMsg: errMsg} }
			continue
		}
		// short cluster
		// arg starts with single '-'
		runes := []rune(arg[1:])
		// we need to process index in runes, but value remainder should be original string after char
		// Map rune index to byte index: since short flags are ascii, use bytes.
		// Use byte loop.
		j := 1 // byte index in arg
		for j < len(arg) {
			ch := rune(arg[j])
			fd := findShortFlag(ch)
			if fd == nil {
				return parseResult{errMsg: formatUnknownShort(string(ch))}
			}
			if fd.Kind == "bool" {
				cli.setBool(fd.Long, true)
				if fd.Long == "help" || fd.Long == "version" {
					cli.helpVersionOrder = append(cli.helpVersionOrder, fd.Long)
				}
				j++
				continue
			}
			// non-bool short: value is rest of token after this char, or next arg
			var val string
			if j+1 < len(arg) {
				val = arg[j+1:]
				j = len(arg)
			} else {
				// need next
				if i >= len(args) {
					typeName := "string"
					return parseResult{errMsg: fmt.Sprintf("--%s: expected %s value but got \"EOL\" (<EOL>)", fd.Long, typeName)}
				}
				next := args[i]
				if next != "-" && strings.HasPrefix(next, "-") && len(next) > 1 {
					kind := tokenKindDesc(next)
					return parseResult{errMsg: fmt.Sprintf("--%s: expected string value but got %q (%s); perhaps try --%s=%q?", fd.Long, next, kind, fd.Long, next)}
				}
				val = next
				i++
