	i := 0
	afterDashDash := false
	for i < len(args) {
		arg := args[i]
		i++
		if afterDashDash {
			if errMsg := addPositional(cli, arg); errMsg != "" { return parseResult{errMsg: errMsg} }
			continue
		}
		if arg == "--" {
			afterDashDash = true
			continue
		}
		if arg == "-" || !strings.HasPrefix(arg, "-") {
			if errMsg := addPositional(cli, arg); errMsg != "" { return parseResult{errMsg: errMsg} }
			continue
		}
		if strings.HasPrefix(arg, "--") {
			raw := arg[2:]
			name := raw
			var attached *string
			if idx := strings.Index(raw, "="); idx >= 0 {
				name = raw[:idx]
				v := raw[idx+1:]
