		return "long flag"
	}
	return "short flag"
}

func parseArgs(args []string) parseResult {
	cli := &CLI{
		Lexer: "autodetect",
		Style: "swapoff",
		Formatter: "terminal",
		HTMLTabWidth: 8,
		HTMLBaseLine: 1,
	}
	// defaults for HTMLTabWidth was set; need know if user set? It's default 8 always.
	i := 0
	afterDashDash := false
	for i < len(args) {
		arg := args[i]
		i++
		if afterDashDash {
			if errMsg := addPositional(cli, arg); errMsg != "" { return parseResult{errMsg: errMsg} }
			continue
		}
		if arg == "--" {
			afterDashDash = true
			continue
		}
		if arg == "-" || !strings.HasPrefix(arg, "-") {
			if errMsg := addPositional(cli, arg); errMsg != "" { return parseResult{errMsg: errMsg} }
			continue
		}
		if strings.HasPrefix(arg, "--") {
			raw := arg[2:]
			name := raw
			var attached *string
			if idx := strings.Index(raw, "="); idx >= 0 {
				name = raw[:idx]
				v := raw[idx+1:]
				attached = &v
			}
			fd := findLongFlag(name)
			if fd == nil {
				return parseResult{errMsg: formatUnknownLong(name)}
			}
			// handle bool/string etc.
			if fd.Kind == "bool" {
				var v bool
				if attached != nil {
					b, ok := parseBoolValue(*attached)
					if !ok {
						return parseResult{errMsg: fmt.Sprintf("--%s: bool value must be true, 1, yes, false, 0 or no but got %q", fd.Long, *attached)}
					}
					v = b
				} else {
					v = true
				}
				cli.setBool(fd.Long, v)
				if fd.Long == "help" || fd.Long == "version" {
					cli.helpVersionOrder = append(cli.helpVersionOrder, fd.Long)
				}
				continue
			}
			// non-bool needs value
			var val string
			if attached != nil {
				val = *attached
			} else {
				// need next token
				if i >= len(args) {
					typeName := "string"
					if fd.Kind == "int" { typeName = "int" }
					if fd.Kind == "existingdir" { typeName = "file" }
					return parseResult{errMsg: fmt.Sprintf("--%s: expected %s value but got \"EOL\" (<EOL>)", fd.Long, typeName)}
				}
				next := args[i]
				if next != "-" && strings.HasPrefix(next, "-") && len(next) > 1 {
					kind := tokenKindDesc(next)
					typeName := "string"
					if fd.Kind == "int" { typeName = "int" }
					if fd.Kind == "existingdir" { typeName = "file" }
					return parseResult{errMsg: fmt.Sprintf("--%s: expected %s value but got %q (%s); perhaps try --%s=%q?", fd.Long, typeName, next, kind, fd.Long, next)}
				}
				val = next
				i++
			}
			// process value by kind
			if errMsg := setNonBool(cli, fd, val); errMsg != "" { return parseResult{errMsg: errMsg} }
			continue
		}
		// short cluster
		// arg starts with single '-'
		runes := []rune(arg[1:])
		// we need to process index in runes, but value remainder should be original string after char
		// Map rune index to byte index: since short flags are ascii, use bytes.
		// Use byte loop.
		j := 1 // byte index in arg
		for j < len(arg) {
			ch := rune(arg[j])
			fd := findShortFlag(ch)
			if fd == nil {
				return parseResult{errMsg: formatUnknownShort(string(ch))}
			}
			if fd.Kind == "bool" {
				cli.setBool(fd.Long, true)
				if fd.Long == "help" || fd.Long == "version" {
					cli.helpVersionOrder = append(cli.helpVersionOrder, fd.Long)
				}
				j++
				continue
			}
			// non-bool short: value is rest of token after this char, or next arg
			var val string
			if j+1 < len(arg) {
				val = arg[j+1:]
				j = len(arg)
			} else {
				// need next
				if i >= len(args) {
					typeName := "string"
					return parseResult{errMsg: fmt.Sprintf("--%s: expected %s value but got \"EOL\" (<EOL>)", fd.Long, typeName)}
				}
				next := args[i]
				if next != "-" && strings.HasPrefix(next, "-") && len(next) > 1 {
					kind := tokenKindDesc(next)
					return parseResult{errMsg: fmt.Sprintf("--%s: expected string value but got %q (%s); perhaps try --%s=%q?", fd.Long, next, kind, fd.Long, next)}
				}
				val = next
				i++
				j = len(arg)
			}
			if errMsg := setNonBool(cli, fd, val); errMsg != "" { return parseResult{errMsg: errMsg} }
		}
	}
	// after scanning, hooks help/version in order of appearance
	if len(cli.helpVersionOrder) > 0 {
		first := cli.helpVersionOrder[0]
		if first == "help" {
			return parseResult{cli: cli, hook: "help"}
		} else {
			return parseResult{cli: cli, hook: "version"}
		}
	}
	// enum validation for formatter (final value)
	validFormatters := map[string]bool{"html":true,"json":true,"noop":true,"svg":true,"terminal":true,"terminal16":true,"terminal16m":true,"terminal256":true,"terminal8":true,"tokens":true}
	if !validFormatters[cli.Formatter] {
		return parseResult{errMsg: fmt.Sprintf("--formatter must be one of \"html\",\"json\",\"noop\",\"svg\",\"terminal\",\"terminal16\",\"terminal16m\",\"terminal256\",\"terminal8\",\"tokens\" but got %q", cli.Formatter)}
	}
	return parseResult{cli: cli}
}

func setNonBool(cli *CLI, fd *FlagDef, val string) string {
	switch fd.Kind {
	case "string", "enum":
		cli.setString(fd.Long, val)
		return ""
	case "int":
		v, err := strconv.ParseInt(val, 10, 64)
		if err != nil {
			return fmt.Sprintf("--%s: expected a valid 64 bit int but got %q", fd.Long, val)
		}
		cli.setInt(fd.Long, v)
		return ""
	case "existingdir":
		abs, _ := filepath.Abs(val)
		info, err := os.Stat(abs)
		if err != nil {
			// err.Error() is "stat /abs/path: ..."
			return fmt.Sprintf("--%s: %s", fd.Long, err.Error())
		}
		if !info.IsDir() {
			return fmt.Sprintf("--%s: %q exists but is not a directory", fd.Long, abs)
		}
		cli.XML = abs
		return ""
	}
	return ""
}

func addPositional(cli *CLI, arg string) string {
	if arg == "-" {
		cli.Files = append(cli.Files, arg)
		return ""
	}
	abs, _ := filepath.Abs(arg)
	info, err := os.Stat(abs)
	if err != nil {
		return fmt.Sprintf("[<files> ...]: %s", err.Error())
	}
	if info.IsDir() {
		return fmt.Sprintf("[<files> ...]: %q exists but is a directory", abs)
	}
	cli.Files = append(cli.Files, abs)
	return ""
}
EOF
"}

{"command":"cat > help.go <<'EOF'
package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
	"syscall"
	"unsafe"
)

func helpWidth() int {
	// try ioctl on stdout, stderr, stdin
	for _, fd := range []uintptr{1, 2, 0} {
		if w := terminalWidth(fd); w > 0 {
			return w
		}
	}
	if v := os.Getenv("COLUMNS"); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 {
			return n
		}
	}
	return 80
}
type winsize struct {
	Row, Col, Xpixel, Ypixel uint16
}
func terminalWidth(fd uintptr) int {
	var ws winsize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if errno != 0 {
		return 0
	}
	return int(ws.Col)
}

type helpItem struct {
	Term string
	Desc string
}
type helpSection struct {
	Title string
	Column int
	Items []helpItem
}

func wrapWords(text string, avail int, first bool) []string {
	if avail < 1 {
		avail = 1
	}
	words := strings.Fields(text)
	var lines []string
	var cur string
	for _, w := range words {
		if cur == "" {
			cur = w
		} else if len(cur)+1+len(w) <= avail {
			cur += " " + w
		} else {
			lines = append(lines, cur)
			cur = w
		}
	}
	if cur != "" {
		lines = append(lines, cur)
	}
	if len(lines) == 0 {
		return []string{""}
	}
	return lines
}

func writeHelp(w io.Writer, prog string) {
	width := helpWidth()
	// If width is 80, we can generate via algorithm and expect matches; test later.
	fmt.Fprintf(w, "Usage: %s [<files> ...] [flags]\n", prog)
	fmt.Fprintf(w, "\n")
	desc := "Chroma is a general purpose syntax highlighting library and corresponding command, for Go."
	for _, line := range wrapWords(desc, width, true) {
		fmt.Fprintln(w, line)
	}
	fmt.Fprintf(w, "\n")
	sections := []helpSection{
		{Title: "Arguments:", Column: 19, Items: []helpItem{
			{Term: "  [<files> ...]", Desc: "Files to highlight."},
		}},
		{Title: "Flags:", Column: 27, Items: []helpItem{
			{Term: "  -h, --help", Desc: "Show context-sensitive help."},
			{Term: "      --version", Desc: "Show version."},
			{Term: "      --list", Desc: "List lexers, styles and formatters."},
			{Term: "      --unbuffered", Desc: "Do not buffer output."},
			{Term: "      --trace", Desc: "Trace lexer states as they are traversed."},
			{Term: "      --check", Desc: "Do not format, check for tokenisation errors instead."},
			{Term: "      --filename=STRING", Desc: "Filename to use for selecting a lexer when reading from stdin."},
			{Term: "      --fail", Desc: "Exit silently with status 1 if no specific lexer was found."},
		}},
		{Title: "Select lexer and style:", Column: 30, Items: []helpItem{
			{Term: "  -l, --lexer=\"autodetect\"", Desc: "Lexer to use when formatting or path to an XML file to load."},
			{Term: "  -s, --style=\"swapoff\"", Desc: "Style to use for formatting or path to an XML file to load."},
		}},
		{Title: "Output format:", Column: 32, Items: []helpItem{
			{Term: "  -f, --formatter=\"terminal\"", Desc: "Formatter to use."},
			{Term: "      --json", Desc: "Convenience flag to use JSON formatter."},
			{Term: "      --html", Desc: "Convenience flag to use HTML formatter."},
			{Term: "      --svg", Desc: "Convenience flag to use SVG formatter."},
		}},
		{Title: "HTML formatter options:", Column: 35, Items: []helpItem{
			{Term: "  --html-prefix=PREFIX", Desc: "HTML CSS class prefix."},
			{Term: "  --html-styles", Desc: "Output HTML CSS styles."},
			{Term: "  --html-all-styles", Desc: "Output all HTML CSS styles, including redundant ones."},
			{Term: "  --html-only", Desc: "Output HTML fragment."},
			{Term: "  --html-inline-styles", Desc: "Output HTML with inline styles (no classes)."},
			{Term: "  --html-tab-width=8", Desc: "Set the HTML tab width."},
			{Term: "  --html-lines", Desc: "Include line numbers in output."},
			{Term: "  --html-lines-table", Desc: "Split line numbers and code in a HTML table"},
			{Term: "  --html-lines-style=STRING", Desc: "Style for line numbers."},
			{Term: "  --html-highlight=N[:M][,...]", Desc: "Highlight these lines."},
			{Term: "  --html-highlight-style=STRING", Desc: "Style used for highlighting lines."},
			{Term: "  --html-base-line=1", Desc: "Base line number."},
			{Term: "  --html-prevent-surrounding-pre", Desc: "Prevent the surrounding pre tag."},
			{Term: "  --html-linkable-lines", Desc: "Make the line numbers linkable and be a link to themselves."},
		}},
	}
	for si, sec := range sections {
		if si > 0 {
			fmt.Fprintf(w, "\n")
		}
		fmt.Fprintf(w, "%s\n", sec.Title)
		for _, item := range sec.Items {
			col := sec.Column
			avail := width - col
			if avail < 1 {
				avail = 1
			}
			wrapped := wrapWords(item.Desc, avail, true)
			// if term length would leave <4 spaces gap, put description on next line
			if col - len(item.Term) < 4 {
				fmt.Fprintf(w, "%s\n", item.Term)
				for _, wl := range wrapped {
					fmt.Fprintf(w, "%s%s\n", strings.Repeat(" ", col), wl)
				}
			} else {
				// first line
				padding := strings.Repeat(" ", col - len(item.Term))
				fmt.Fprintf(w, "%s%s%s\n", item.Term, padding, wrapped[0])
				for _, wl := range wrapped[1:] {
					fmt.Fprintf(w, "%s%s\n", strings.Repeat(" ", col), wl)
				}
			}
		}
	}
}
EOF
"}

