actions.command:
cat > xml_lexer.go <<'EOF'
package main

import (
	"bytes"
	"encoding/xml"
	"fmt"
	"io"
	"strconv"
	"strings"
)

type xmlAttr struct {
	name, value string
}

func attrValues(se xml.StartElement, name string) []string {
	var out []string
	for _, a := range se.Attr {
		if a.Name.Local == name {
			out = append(out, a.Value)
		}
	}
	return out
}
func attrValue(se xml.StartElement, name string) (string, bool) {
	vs := attrValues(se, name)
	if len(vs) > 0 {
		return vs[0], true
	}
	return "", false
}

// text content of an element (until its end)
func readElementText(dec *xml.Decoder) (string, error) {
	var sb strings.Builder
	depth := 1
	for depth > 0 {
		tok, err := dec.Token()
		if err != nil {
			return "", err
		}
		switch t := tok.(type) {
		case xml.CharData:
			sb.Write([]byte(t))
		case xml.StartElement:
			depth++
			_ = t
		case xml.EndElement:
			depth--
		}
	}
	return sb.String(), nil
}
func skipElement(dec *xml.Decoder) error {
	depth := 1
	for depth > 0 {
		tok, err := dec.Token()
		if err != nil {
			return err
		}
		switch tok.(type) {
		case xml.StartElement:
			depth++
		case xml.EndElement:
			depth--
		}
	}
	return nil
}

func loadLexerXML(data []byte, source string) (*LexerDef, error) {
	dec := xml.NewDecoder(bytes.NewReader(data))
	// find config
	foundConfig := false
	var lexer *LexerDef
	lexer = &LexerDef{Flags: map[string]bool{}, States: map[string][]Rule{}}
	// state for parsing
	// Phase 1: find config start
	for !foundConfig {
		tok, err := dec.Token()
		if err != nil {
			if err == io.EOF {
				return nil, fmt.Errorf("could not find <config> element")
			}
			return nil, fmt.Errorf("%s: %s", source, err.Error())
		}
		if se, ok := tok.(xml.StartElement); ok && se.Name.Local == "config" {
			foundConfig = true
			// parse config contents
			if err := parseLexerConfig(dec, lexer, source); err != nil {
				return nil, err
			}
			break
		}
	}
	// Phase2: find rules
	foundRules := false
	for !foundRules {
		tok, err := dec.Token()
		if err != nil {
			if err == io.EOF {
				break
			}
			return nil, fmt.Errorf("%s: %s", source, err.Error())
		}
		if se, ok := tok.(xml.StartElement); ok && se.Name.Local == "rules" {
			foundRules = true
			if err := parseLexerRules(dec, lexer, source); err != nil {
				return nil, err
			}
			break
		}
	}
	// validations
	if _, ok := lexer.States["root"]; !ok {
		return nil, fmt.Errorf("no \"root\" state")
	}
	// include validation & token / pattern compile validation
	for stateName, rules := range lexer.States {
		for idx, r := range rules {
			if r.Include != "" {
				if _, ok := lexer.States[r.Include]; !ok {
					return nil, fmt.Errorf("invalid include state %q", r.Include)
				}
				continue
			}
			// emitter validation
			if r.Emitter != nil {
				if err := validateEmitterTypes(lexer, source, r.Emitter); err != nil {
					return nil, err
				}
				if r.Emitter.Kind == "b" {
					// group count validation
					pat := ""
					if r.Pattern != nil { pat = *r.Pattern }
					groups := countCaptureGroups(pat)
					if groups != len(r.Emitter.Groups) {
						return nil, fmt.Errorf("%s: %s: %s: number of groups %d does not match number of emitters %d", lexer.Name, stateName, pat, groups, len(r.Emitter.Groups))
					}
				}
				if r.Emitter.Kind == "unknown" {
					return nil, fmt.Errorf("%s: failed to compile rules: %s: unknown emitter %q: not serialisable", lexer.Name, source, r.Emitter.Lexer)
				}
			}
			// pattern compile check
			if r.Pattern != nil {
				pat := *r.Pattern
				if _, err := compileCheckPattern(pat, lexer.Flags); err != nil {
					return nil, fmt.Errorf("failed to compile rule %s.%d: %s", stateName, idx, err.Error())
				}
			}
		}
	}
	return lexer, nil
}

func validateEmitterTypes(lexer *LexerDef, source string, e *Emitter) error {
	switch e.Kind {
	case "t":
		if !isValidTokenType(string(e.Token)) {
			return fmt.Errorf("%s: failed to compile rules: %s: %s does not belong to TokenType values", lexer.Name, source, string(e.Token))
		}
	case "b":
		for _, g := range e.Groups {
			// groups are Emitter values
			gg := g
			if err := validateEmitterTypes(lexer, source, &gg); err != nil {
				return err
			}
		}
	case "ubg":
		for _, t := range e.UbgTokens {
			if !isValidTokenType(string(t)) {
				return fmt.Errorf("%s: failed to compile rules: %s: %s does not belong to TokenType values", lexer.Name, source, string(t))
			}
		}
	}
	return nil
}

func compileCheckPattern(pat string, flags map[string]bool) (bool, error) {
	// Try to compile using Go regexp with trivial transforms. If fails, return error formatted like Go regexp error but with \G prefix.
	// First attempt trivial transform compilation
	reStrPat := pat
	// Use tryTrivialTransform for compilation test: it returns compiled regex or error.
	_, err := tryTrivialTransform(reStrPat, flags)
	if err == nil {
		return true, nil
	}
	// error from tryTrivialTransform is Go error containing the wrapped pattern (?...)
	msg := err.Error()
	// Insert \G after opening backtick Quote
	// Error example: error parsing regexp: missing closing ): `(?m)(?:()`
	// We want: error parsing regexp: missing closing ) in `\G(?m)(?:()`
	// Go's original error for "("? Their fork might format differently, approximate:
	// Replace "`(?" with "`\\G(?"
	msg = strings.Replace(msg, "`(?", "`\\G(?", 1)
	// Also Go error may say "missing closing ): " vs original "missing closing ) in " - leave as is (close enough)
	return false, fmt.Errorf("%s", msg)
}

func countCaptureGroups(pat string) int {
	// count '(' that are capturing: not \-, not in class, not (?: (?= (?! (?<= (?<! (?i etc, not (?P<name> / (?<name> count as capture)
	count := 0
	inClass := false
	escaped := false
	for i := 0; i < len(pat); i++ {
		c := pat[i]
		if escaped {
			escaped = false
			continue
		}
		if c == '\\' {
			escaped = true
			continue
		}
		if inClass {
			if c == ']' { inClass = false }
			continue
		}
		if c == '[' {
			inClass = true
			continue
		}
		if c == '(' {
			// check next
			if i+1 < len(pat) && pat[i+1] == '?' {
				// (?: (?= (?! (?<= (?<! (?flags) etc are non-capturing, except (?P< or (?< name is capture
				if i+2 < len(pat) && (pat[i+2] == 'P' || pat[i+2] == '<') {
					// (?< followed by = or ! is lookbehind, not capture
					if pat[i+2] == '<' && i+3 < len(pat) && (pat[i+3] == '=' || pat[i+3] == '!') {
						continue
					}
					count++
					continue
				}
				continue
			}
			count++
		}
	}
	return count
}

func parseLexerConfig(dec *xml.Decoder, lexer *LexerDef, source string) error {
	for {
		tok, err := dec.Token()
		if err != nil {
			if err == io.EOF {
				return fmt.Errorf("could not find <config> element") // ?? after config start, EOF is syntax?
			}
			return fmt.Errorf("%s: %s", source, err.Error())
		}
		switch t := tok.(type) {
		case xml.StartElement:
			name := t.Name.Local
			switch name {
			case "name":
				txt, err := readElementText(dec); if err != nil { return fmt.Errorf("%s: %s", source, err.Error()) }
				lexer.Name = txt
			case "alias":
				txt, err := readElementText(dec); if err != nil { return fmt.Errorf("%s: %s", source, err.Error()) }
				lexer.Aliases = append(lexer.Aliases, txt)
			case "filename":
				txt, err := readElementText(dec); if err != nil { return fmt.Errorf("%s: %s", source, err.Error()) }
				lexer.Filenames = append(lexer.Filenames, txt)
			case "mime_type":
				txt, err := readElementText(dec); if err != nil { return fmt.Errorf("%s: %s", source, err.Error()) }
				lexer.Mimetypes = append(lexer.Mimetypes, txt)
			case "priority":
				txt, err := readElementText(dec); if err != nil { return fmt.Errorf("%s: %s", source, err.Error()) }
				v, err := strconv.ParseFloat(strings.TrimSpace(txt), 64)
				if err != nil {
					return fmt.Errorf("%s: %s", source, err.Error())
				}
				lexer.Priority = v
				lexer.HasPriority = true
			case "analyse":
				// parse nested regex elements
				ad := &AnalyseDef{First: false}
				if v, ok := attrValue(t, "first"); ok {
					ad.First = (v == "true")
				}
				for {
					tok2, err := dec.Token()
					if err != nil { return fmt.Errorf("%s: %s", source, err.Error()) }
					if se, ok := tok2.(xml.StartElement); ok && se.Name.Local == "regex" {
						pat, _ := attrValue(se, "pattern")
						scoreStr, _ := attrValue(se, "score")
						score, err := strconv.ParseFloat(scoreStr, 64)
						if err != nil { return fmt.Errorf("%s: %s", source, err.Error()) }
						ad.Patterns = append(ad.Patterns, AnalysePattern{pat, score})
						// consume if not self-closing? regex element may be self closing (dec token for /> gives Start then End)
						// readElementText-like skip
						// if element had content (unlikely), skip
						// Peek handling: we need to consume its end if present. Using skip if ... StartElement for self-closing in Go xml decoder yields both Start and End tokens.
						// Our loop will see EndElement for regex next iteration and ignore.
					}
					if ee, ok := tok2.(xml.EndElement); ok && ee.Name.Local == "analyse" {
						break
					}
				}
				lexer.Analyse = ad
			case "dot_all", "case_insensitive", "ensure_nl", "not_multiline":
				txt, err := readElementText(dec); if err != nil { return fmt.Errorf("%s: %s", source, err.Error()) }
				b, err := strconv.ParseBool(strings.TrimSpace(txt))
				if err != nil {
					return fmt.Errorf("%s: %s", source, err.Error())
				}
				if lexer.Flags == nil { lexer.Flags = map[string]bool{} }
				lexer.Flags[name] = b
			default:
				// skip unknown element subtree
				if err := skipElement(dec); err != nil { return fmt.Errorf("%s: %s", source, err.Error()) }
			}
		case xml.EndElement:
			if t.Name.Local == "config" {
				return nil
			}
		}
	}
}

func parseLexerRules(dec *xml.Decoder, lexer *LexerDef, source string) error {
	// inside <rules>: states
	for {
		tok, err := dec.Token()
		if err != nil {
			if err == io.EOF {
				return nil
			}
			return fmt.Errorf("%s: %s", source, err.Error())
		}
		switch t := tok.(type) {
		case xml.StartElement:
			if t.Name.Local == "state" {
				stateName, _ := attrValue(t, "name")
				rules, err := parseStateRules(dec, lexer, source, stateName)
				if err != nil { return err }
				lexer.States[stateName] = rules
			} else {
				if err := skipElement(dec); err != nil { return fmt.Errorf("%s: %s", source, err.Error()) }
			}
		case xml.EndElement:
			if t.Name.Local == "rules" {
				return nil
			}
		}
	}
}

func parseStateRules(dec *xml.Decoder, lexer *LexerDef, source string, stateName string) ([]Rule, error) {
	var rules []Rule
	for {
		tok, err := dec.Token()
		if err != nil {
			return nil, fmt.Errorf("%s: %s", source, err.Error())
		}
		switch t := tok.(type) {
		case xml.StartElement:
			if t.Name.Local == "rule" {
				rule, err := parseSingleRule(dec, lexer, source, t)
				if err != nil { return nil, err }
				rules = append(rules, rule)
			} else {
				if err := skipElement(dec); err != nil { return nil, fmt.Errorf("%s: %s", source, err.Error()) }
			}
		case xml.EndElement:
			if t.Name.Local == "state" {
				return rules, nil
			}
		}
	}
}

func parseSingleRule(dec *xml.Decoder, lexer *LexerDef, source string, ruleStart xml.StartElement) (Rule, error) {
	var rule Rule
	if pat, ok := attrValue(ruleStart, "pattern"); ok {
		p := pat
		rule.Pattern = &p
		rule.RawPattern = pat
	}
	// children
	for {
		tok, err := dec.Token()
		if err != nil {
			return rule, fmt.Errorf("%s: %s", source, err.Error())
		}
		switch t := tok.(type) {
		case xml.StartElement:
			switch t.Name.Local {
			case "token":
				typ, _ := attrValue(t, "type")
				rule.Emitter = &Emitter{Kind: "t", Token: TT(typ)}
				if err := skipElementContent(dec, t); err != nil { return rule, err }
			case "bygroups":
				groups, err := parseBygroups(dec, source)
				if err != nil { return rule, err }
				rule.Emitter = &Emitter{Kind: "b", Groups: groups}
			case "using":
				lx, _ := attrValue(t, "lexer")
				rule.Emitter = &Emitter{Kind: "u", Lexer: lx}
				if err := skipElementContent(dec, t); err != nil { return rule, err }
			case "usingself":
				st, _ := attrValue(t, "state")
				rule.Emitter = &Emitter{Kind: "s", State: st}
				if err := skipElementContent(dec, t); err != nil { return rule, err }
			case "usingbygroup":
				ubg, err := parseUsingByGroup(dec, source)
				if err != nil { return rule, err }
				rule.Emitter = ubg
			case "push":
				states := []string{}
				for _, v := range attrValues(t, "state") {
					states = append(states, strings.Fields(v)...)
				}
				rule.Mutators = append(rule.Mutators, Mutator{Kind: "push", States: states})
				if err := skipElementContent(dec, t); err != nil { return rule, err }
			case "pop":
				depthStr, ok := attrValue(t, "depth")
				depth := 1
				if ok {
					d, err := strconv.ParseInt(depthStr, 10, 64)
					if err != nil {
						return rule, fmt.Errorf("%s: failed to compile rules: %s: %s", lexer.Name, source, err.Error())
					}
					depth = int(d)
				}
				rule.Mutators = append(rule.Mutators, Mutator{Kind: "pop", Depth: depth})
				if err := skipElementContent(dec, t); err != nil { return rule, err }
			case "combined":
				states := []string{}
				for _, v := range attrValues(t, "state") {
					states = append(states, strings.Fields(v)...)
				}
				rule.Mutators = append(rule.Mutators, Mutator{Kind: "combined", States: states})
				if err := skipElementContent(dec, t); err != nil { return rule, err }
			case "include":
				st, _ := attrValue(t, "state")
				rule.Include = st
				if err := skipElementContent(dec, t); err != nil { return rule, err }
			case "mutators":
				muts, err := parseMutators(dec, source, lexer)
				if err != nil { return rule, err }
				rule.Mutators = append(rule.Mutators, muts...)
			default:
				// unknown emitter
				rule.Emitter = &Emitter{Kind: "unknown", Lexer: t.Name.Local}
				if err := skipElementContent(dec, t); err != nil { return rule, err }
			}
		case xml.EndElement:
			if t.Name.Local == "rule" {
				return rule, nil
			}
		}
	}
}

// If element was self-closing, decoder gives Start then End. Our skipElementContent expects to consume up to matching end including possible nested start error handling not here.
// It works for self closing as End will arrive.
func skipElementContent(dec *xml.Decoder, start xml.StartElement) error {
	// Determine if this start may contain nested elements -> original would error unexpected..., but here skip.
	depth := 1
	for depth > 0 {
		tok, err := dec.Token()
		if err != nil {
			return err
		}
		switch tok.(type) {
		case xml.StartElement:
			depth++
		case xml.EndElement:
			depth--
		}
	}
	return nil
}

func parseBygroups(dec *xml.Decoder, source string) ([]Emitter, error) {
	var groups []Emitter
	for {
		tok, err := dec.Token()
		if err != nil { return nil, fmt.Errorf("%s: %s", source, err.Error()) }
		switch t := tok.(type) {
		case xml.StartElement:
			switch t.Name.Local {
			case "token":
				typ, _ := attrValue(t, "type")
				groups = append(groups, Emitter{Kind: "t", Token: TT(typ)})
				if err := skipElementContent(dec, t); err != nil { return nil, err }
			case "using":
				lx, _ := attrValue(t, "lexer")
				groups = append(groups, Emitter{Kind: "u", Lexer: lx})
				if err := skipElementContent(dec, t); err != nil { return nil, err }
			case "usingself":
				st, _ := attrValue(t, "state")
				groups = append(groups, Emitter{Kind: "s", State: st})
				if err := skipElementContent(dec, t); err != nil { return nil, err }
			default:
				groups = append(groups, Emitter{Kind: "unknown", Lexer: t.Name.Local})
				if err := skipElementContent(dec, t); err != nil { return nil, err }
			}
		case xml.EndElement:
			if t.Name.Local == "bygroups" {
				return groups, nil
			}
		}
	}
}

func parseUsingByGroup(dec *xml.Decoder, source string) (*Emitter, error) {
	e := &Emitter{Kind: "ubg"}
	for {
		tok, err := dec.Token()
		if err != nil { return nil, fmt.Errorf("%s: %s", source, err.Error()) }
		switch t := tok.(type) {
		case xml.StartElement:
			switch t.Name.Local {
			case "sublexer_name_group":
				txt, err := readElementText(dec); if err != nil { return nil, err }
				v, _ := strconv.Atoi(strings.TrimSpace(txt)); e.SubNameGroup = v
			case "code_group":
				txt, err := readElementText(dec); if err != nil { return nil, err }
				v, _ := strconv.Atoi(strings.TrimSpace(txt)); e.CodeGroup = v
			case "emitters":
				for {
					tok2, err := dec.Token()
					if err != nil { return nil, err }
					if se, ok := tok2.(xml.StartElement); ok && se.Name.Local == "token" {
						typ, _ := attrValue(se, "type"); e.UbgTokens = append(e.UbgTokens, TT(typ))
						if err := skipElementContent(dec, se); err != nil { return nil, err }
					}
					if ee, ok := tok2.(xml.EndElement); ok && ee.Name.Local == "emitters" { break }
				}
			default:
				if err := skipElement(dec); err != nil { return nil, err }
			}
		case xml.EndElement:
			if t.Name.Local == "usingbygroup" {
				return e, nil
			}
		}
	}
}

func parseMutators(dec *xml.Decoder, source string, lexer *LexerDef) ([]Mutator, error) {
	var muts []Mutator
	for {
		tok, err := dec.Token()
		if err != nil { return nil, fmt.Errorf("%s: %s", source, err.Error()) }
		switch t := tok.(type) {
		case xml.StartElement:
			switch t.Name.Local {
			case "push":
				states := []string{}
				for _, v := range attrValues(t, "state") { states = append(states, strings.Fields(v)...) }
				muts = append(muts, Mutator{Kind: "push", States: states})
				if err := skipElementContent(dec, t); err != nil { return nil, err }
			case "pop":
				depth := 1
				if ds, ok := attrValue(t, "depth"); ok {
					d, err := strconv.ParseInt(ds, 10, 64)
					if err != nil { return nil, fmt.Errorf("%s: failed to compile rules: %s: %s", lexer.Name, source, err.Error()) }
					depth = int(d)
				}
				muts = append(muts, Mutator{Kind: "pop", Depth: depth})
				if err := skipElementContent(dec, t); err != nil { return nil, err }
			case "combined":
				states := []string{}
				for _, v := range attrValues(t, "state") { states = append(states, strings.Fields(v)...) }
				muts = append(muts, Mutator{Kind: "combined", States: states})
				if err := skipElementContent(dec, t); err != nil { return nil, err }
			default:
				if err := skipElement(dec); err != nil { return nil, err }
			}
		case xml.EndElement:
			if t.Name.Local == "mutators" {
				return muts, nil
			}
		}
	}
}
EOF

