package main

import (
	"bytes"
	"encoding/xml"
	"fmt"
	"io"
	"strings"
)

func loadStyleXML(data []byte) (*Style, error) {
	dec := xml.NewDecoder(bytes.NewReader(data))
	// find first start element
	var root *xml.StartElement
	for {
		tok, err := dec.Token()
		if err != nil {
			return nil, err // EOF etc
		}
		if se, ok := tok.(xml.StartElement); ok {
			r := se
			root = &r
			break
		}
	}
	// attrs of root: only "name" allowed
	var styleName string
	for _, a := range root.Attr {
		if a.Name.Local == "name" {
			styleName = a.Value
		} else {
			return nil, fmt.Errorf("unexpected attribute %s", a.Name.Local)
		}
	}
	if styleName == "" {
		return nil, fmt.Errorf("missing style name attribute")
	}
	entries := map[TT]StyleEntry{}
	// loop inside root
	for {
		tok, err := dec.Token()
		if err != nil {
			return nil, err
		}
		switch t := tok.(type) {
		case xml.StartElement:
			if t.Name.Local != "entry" {
				return nil, fmt.Errorf("unexpected element %s", t.Name.Local)
			}
			// parse entry attrs
			var typStr, styleStr string
			for _, a := range t.Attr {
				switch a.Name.Local {
				case "type":
					typStr = a.Value
				case "style":
					styleStr = a.Value
				default:
					return nil, fmt.Errorf("unexpected attribute %s", a.Name.Local)
				}
			}
			// consume entry contents: expecting immediate End; if Start inside, unexpected element
			for {
				tok2, err := dec.Token()
				if err != nil {
					return nil, err
				}
				if se, ok := tok2.(xml.StartElement); ok {
					return nil, fmt.Errorf("unexpected element %s", se.Name.Local)
				}
				if ee, ok := tok2.(xml.EndElement); ok && ee.Name.Local == "entry" {
					break
				}
			}
			var tt TT
			if typStr == "" {
				tt = TTBackground
			} else {
				if !isValidTokenType(typStr) {
					return nil, fmt.Errorf("%s does not belong to TokenType values", typStr)
				}
				tt = TT(typStr)
			}
			entry, err := parseStyleEntry(styleStr)
			if err != nil {
				return nil, err
			}
			entries[tt] = entry
		case xml.EndElement:
			// end of root (any name)
			if t.Name.Local == root.Name.Local {
				// Build
				st, err := buildStyle(styleName, entries)
				if err != nil {
					return nil, err
				}
				return st, nil
			}
		case xml.CharData:
			_ = strings.TrimSpace(string(t))
		}
		_ = io.EOF
	}
}
EOF
"}

