{"command":"cat > dump_xml.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

var dumpUnsupported = map[string]string{
	"Go": "warning: \"Go\": unsupported emitter chroma.EmitterFunc: not serialisable",
	"Haxe": "warning: \"Haxe\": unsupported mutator: not serialisable",
	"Raku": "warning: \"Raku\": unsupported emitter chroma.EmitterFunc: not serialisable",
	"reStructuredText": "warning: \"reStructuredText\": unsupported emitter chroma.EmitterFunc: not serialisable",
}
var dumpSkipSilent = map[string]bool{
	"Common Lisp": true, "EmacsLisp": true, "ERB": true, "Go HTML Template": true, "HTTP": true, "PHTML": true, "Svelte": true,
}

func slugForLexer(name string) string {
	s := strings.ToLower(name)
	re := regexp.MustCompile(`[^a-z0-9+#-]+`)
	s = re.ReplaceAllString(s, "_")
	return s
}

func dumpXML(dir string) error {
	// iteration in dumpOrderNames (includes "!" for unsupported)
	for _, entry := range dumpOrderNames {
		if strings.HasPrefix(entry, "!") {
			name := strings.TrimPrefix(entry, "!")
			if msg, ok := dumpUnsupported[name]; ok {
				fmt.Fprintln(os.Stderr, msg)
			} else {
				fmt.Fprintf(os.Stderr, "warning: %q: unsupported emitter chroma.EmitterFunc: not serialisable\n", name)
			}
			continue
		}
		name := entry
		if dumpSkipSilent[name] {
			continue
		}
		ld, ok := findLexerByCanonicalName(name)
		if !ok {
			continue
		}
		if ld.Name == "Go" || ld.Name == "Haxe" || ld.Name == "Raku" || ld.Name == "reStructuredText" {
			// These are in dumpOrder as normal for others? Actually order has ! for them, this case not reached
			continue
		}
		filename := filepath.Join(dir, slugForLexer(name)+".xml")
		if _, err := os.Stat(filename); err == nil {
			fmt.Fprintf(os.Stderr, "warning: %s already exists\n", filename)
			continue
		}
		data := serializeLexerXML(ld)
		// Write with 0600
		f, err := os.OpenFile(filename, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
		if err != nil {
			return err
		}
		if _, err := f.Write(data); err != nil {
			f.Close()
			return err
		}
		if err := f.Close(); err != nil {
			return err
		}
	}
