	// Patterns have &#34; for " and &#39; for '
	// Implement replace: & first to &amp;, then < &lt;, > &gt;, " &#34;, ' &#39;
	r := strings.NewReplacer(
		"&", "&amp;",
		"<", "&lt;",
		">", "&gt;",
		"\"", "&#34;",
		"'", "&#39;",
	)
	return r.Replace(s)
}
func xmlTextEscape(s string) string {
	return xmlEscape(s)
}

func serializeLexerXML(ld *LexerDef) []byte {
	var b strings.Builder
