	for _, a := range ld.Aliases {
		fmt.Fprintf(&b, "    <alias>%s</alias>\n", xmlTextEscape(a))
	}
	for _, f := range ld.Filenames {
		fmt.Fprintf(&b, "    <filename>%s</filename>\n", xmlTextEscape(f))
	}
	for _, m := range ld.Mimetypes {
		fmt.Fprintf(&b, "    <mime_type>%s</mime_type>\n", xmlTextEscape(m))
	}
