		// format priority: Go %v for float? 0.1 -> 0.1, 3 -> 3, -1 -> -1, 1 ->1, 0.5 ->0.5
		fmt.Fprintf(&b, "    <priority>%s</priority>\n", formatFloat(ld.Priority))
	}
