		fmt.Fprintf(&b, "    <analyse first=\"%s\">\n", firstStr)
		for _, ap := range ld.Analyse.Patterns {
			fmt.Fprintf(&b, "      <regex pattern=\"%s\" score=\"%s\"/>\n", xmlEscape(ap.Pattern), formatFloat(ap.Score))
		}
		b.WriteString("    </analyse>\n")
	}
