	// Go default %v for float64 is 'g' ?
	return fmt.Sprintf("%v", f)
}
func sortedKeys(m map[string][]Rule) []string {
	keys := make([]string, 0, len(m))
	for k := range m { keys = append(keys, k) }
	// sort alphabetically
	for i := 0; i < len(keys); i++ {
		for j := i+1; j < len(keys); j++ {
			if keys[j] < keys[i] { keys[i], keys[j] = keys[j], keys[i] }
		}
	}
	return keys
}
func writeRuleXML(b *strings.Builder, r Rule) {
	if r.Include != "" {
		b.WriteString("      <rule>\n")
		fmt.Fprintf(b, "        <include state=\"%s\"/>\n", xmlEscape(r.Include))
		b.WriteString("      </rule>\n")
		return
	}
	patAttr := ""
	isSelf := r.Emitter == nil && len(r.Mutators) == 0
	_ = isSelf
	if r.Pattern != nil {
		patAttr = fmt.Sprintf(" pattern=\"%s\"", xmlEscape(*r.Pattern))
	}
	// check if rule has no children (should be self closing? Original has <rule pattern=".."><token/></rule> etc, and empty default rules have children)
	hasChildren := r.Emitter != nil || len(r.Mutators) > 0
	if !hasChildren {
		fmt.Fprintf(b, "      <rule%s/>\n", patAttr)
		return
	}
	fmt.Fprintf(b, "      <rule%s>\n", patAttr)
	if r.Emitter != nil {
		writeEmitterXML(b, r.Emitter, "        ")
	}
	for _, m := range r.Mutators {
		switch m.Kind {
		case "push":
			// produce duplicate state attributes for multiple states
			attrs := ""
			for _, s := range m.States {
				attrs += fmt.Sprintf(" state=\"%s\"", xmlEscape(s))
			}
			fmt.Fprintf(b, "        <push%s/>\n", attrs)
		case "pop":
			fmt.Fprintf(b, "        <pop depth=\"%d\"/>\n", m.Depth)
		case "combined":
			attrs := ""
			for _, s := range m.States {
				attrs += fmt.Sprintf(" state=\"%s\"", xmlEscape(s))
			}
			fmt.Fprintf(b, "        <combined%s/>\n", attrs)
		}
	}
	b.WriteString("      </rule>\n")
}
func writeEmitterXML(b *strings.Builder, e *Emitter, indent string) {
	switch e.Kind {
	case "t":
		fmt.Fprintf(b, "%s<token type=\"%s\"/>\n", indent, string(e.Token))
	case "u":
		fmt.Fprintf(b, "%s<using lexer=\"%s\"/>\n", indent, xmlEscape(e.Lexer))
	case "s":
		fmt.Fprintf(b, "%s<usingself state=\"%s\"/>\n", indent, xmlEscape(e.State))
	case "b":
		fmt.Fprintf(b, "%s<bygroups>\n", indent)
		for _, g := range e.Groups {
			gg := g
			writeEmitterXML(b, &gg, indent+"  ")
		}
		fmt.Fprintf(b, "%s</bygroups>\n", indent)
	case "ubg":
		fmt.Fprintf(b, "%s<usingbygroup>\n", indent)
		fmt.Fprintf(b, "%s  <sublexer_name_group>%d</sublexer_name_group>\n", indent, e.SubNameGroup)
		fmt.Fprintf(b, "%s  <code_group>%d</code_group>\n", indent, e.CodeGroup)
		fmt.Fprintf(b, "%s  <emitters>\n", indent)
		for _, t := range e.UbgTokens {
			fmt.Fprintf(b, "%s    <token type=\"%s\"/>\n", indent, string(t))
		}
		fmt.Fprintf(b, "%s  </emitters>\n", indent)
		fmt.Fprintf(b, "%s</usingbygroup>\n", indent)
	case "unknown":
		fmt.Fprintf(b, "%s<%s/>\n", indent, e.Lexer)
	}
}
EOF
