{"command":"cat > dump_xml.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

var dumpUnsupported = map[string]string{
	"Go": "warning: \"Go\": unsupported emitter chroma.EmitterFunc: not serialisable",
	"Haxe": "warning: \"Haxe\": unsupported mutator: not serialisable",
	"Raku": "warning: \"Raku\": unsupported emitter chroma.EmitterFunc: not serialisable",
	"reStructuredText": "warning: \"reStructuredText\": unsupported emitter chroma.EmitterFunc: not serialisable",
}
var dumpSkipSilent = map[string]bool{
	"Common Lisp": true, "EmacsLisp": true, "ERB": true, "Go HTML Template": true, "HTTP": true, "PHTML": true, "Svelte": true,
}

func slugForLexer(name string) string {
	s := strings.ToLower(name)
	re := regexp.MustCompile(`[^a-z0-9+#-]+`)
	s = re.ReplaceAllString(s, "_")
	return s
}

func dumpXML(dir string) error {
	// iteration in dumpOrderNames (includes "!" for unsupported)
	for _, entry := range dumpOrderNames {
		if strings.HasPrefix(entry, "!") {
			name := strings.TrimPrefix(entry, "!")
			if msg, ok := dumpUnsupported[name]; ok {
				fmt.Fprintln(os.Stderr, msg)
			} else {
				fmt.Fprintf(os.Stderr, "warning: %q: unsupported emitter chroma.EmitterFunc: not serialisable\n", name)
			}
			continue
		}
		name := entry
		if dumpSkipSilent[name] {
			continue
		}
		ld, ok := findLexerByCanonicalName(name)
		if !ok {
			continue
		}
		if ld.Name == "Go" || ld.Name == "Haxe" || ld.Name == "Raku" || ld.Name == "reStructuredText" {
			// These are in dumpOrder as normal for others? Actually order has ! for them, this case not reached
			continue
		}
		filename := filepath.Join(dir, slugForLexer(name)+".xml")
		if _, err := os.Stat(filename); err == nil {
			fmt.Fprintf(os.Stderr, "warning: %s already exists\n", filename)
			continue
		}
		data := serializeLexerXML(ld)
		// Write with 0600
		f, err := os.OpenFile(filename, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
		if err != nil {
			return err
		}
		if _, err := f.Write(data); err != nil {
			f.Close()
			return err
		}
		if err := f.Close(); err != nil {
			return err
		}
	}
	return nil
}

func xmlEscape(s string) string {
	// Go xml EscapeText escapes < > & ' " as &#34; / &#39; etc? But dumps show &#34; for quote in patterns.
	// For our generation, use encoding/xml escaping via a helper that matches expected observed for patterns containing quotes.
	// Patterns have &#34; for " and &#39; for '
	// Implement replace: & first to &amp;, then < &lt;, > &gt;, " &#34;, ' &#39;
	r := strings.NewReplacer(
		"&", "&amp;",
		"<", "&lt;",
		">", "&gt;",
		"\"", "&#34;",
		"'", "&#39;",
	)
	return r.Replace(s)
}
func xmlTextEscape(s string) string {
	return xmlEscape(s)
}

func serializeLexerXML(ld *LexerDef) []byte {
	var b strings.Builder
	b.WriteString("<lexer>\n  <config>\n")
	fmt.Fprintf(&b, "    <name>%s</name>\n", xmlTextEscape(ld.Name))
	for _, a := range ld.Aliases {
		fmt.Fprintf(&b, "    <alias>%s</alias>\n", xmlTextEscape(a))
	}
	for _, f := range ld.Filenames {
		fmt.Fprintf(&b, "    <filename>%s</filename>\n", xmlTextEscape(f))
	}
	for _, m := range ld.Mimetypes {
		fmt.Fprintf(&b, "    <mime_type>%s</mime_type>\n", xmlTextEscape(m))
	}
	// flags in alphabetical order among themselves: case_insensitive, dot_all, ensure_nl, not_multiline
	flagOrder := []string{"case_insensitive", "dot_all", "ensure_nl", "not_multiline"}
	for _, k := range flagOrder {
		if v, ok := ld.Flags[k]; ok && v {
			fmt.Fprintf(&b, "    <%s>true</%s>\n", k, k)
		} else if ok && !v {
			// original would not output false? assume skip
		}
	}
	// also other flags present?
	for k, v := range ld.Flags {
		found := false
		for _, kk := range flagOrder { if kk == k { found = true } }
		if !found && v {
			fmt.Fprintf(&b, "    <%s>true</%s>\n", k, k)
		}
	}
	if ld.HasPriority {
		// format priority: Go %v for float? 0.1 -> 0.1, 3 -> 3, -1 -> -1, 1 ->1, 0.5 ->0.5
		fmt.Fprintf(&b, "    <priority>%s</priority>\n", formatFloat(ld.Priority))
	}
	if ld.Analyse != nil {
		firstStr := "false"
		if ld.Analyse.First { firstStr = "true" }
		fmt.Fprintf(&b, "    <analyse first=\"%s\">\n", firstStr)
		for _, ap := range ld.Analyse.Patterns {
			fmt.Fprintf(&b, "      <regex pattern=\"%s\" score=\"%s\"/>\n", xmlEscape(ap.Pattern), formatFloat(ap.Score))
		}
		b.WriteString("    </analyse>\n")
	}
	b.WriteString("  </config>\n  <rules>\n")
	// state order: deterministic sorted(?) but original random. We will use sorted state names for determinism.
	stateNames := sortedKeys(ld.States)
	for _, stateName := range stateNames {
		rules := ld.States[stateName]
		fmt.Fprintf(&b, "    <state name=\"%s\">\n", xmlEscape(stateName))
		for _, r := range rules {
			writeRuleXML(&b, r)
		}
		b.WriteString("    </state>\n")
	}
	b.WriteString("  </rules>\n</lexer>")
	return []byte(b.String())
}
func formatFloat(f float64) string {
	// Go default %v for float64 is 'g' ?
	return fmt.Sprintf("%v", f)
}
func sortedKeys(m map[string][]Rule) []string {
	keys := make([]string, 0, len(m))
	for k := range m { keys = append(keys, k) }
	// sort alphabetically
	for i := 0; i < len(keys); i++ {
		for j := i+1; j < len(keys); j++ {
			if keys[j] < keys[i] { keys[i], keys[j] = keys[j], keys[i] }
		}
	}
	return keys
}
func writeRuleXML(b *strings.Builder, r Rule) {
	if r.Include != "" {
		b.WriteString("      <rule>\n")
		fmt.Fprintf(b, "        <include state=\"%s\"/>\n", xmlEscape(r.Include))
		b.WriteString("      </rule>\n")
		return
	}
	patAttr := ""
	isSelf := r.Emitter == nil && len(r.Mutators) == 0
	_ = isSelf
	if r.Pattern != nil {
		patAttr = fmt.Sprintf(" pattern=\"%s\"", xmlEscape(*r.Pattern))
	}
	// check if rule has no children (should be self closing? Original has <rule pattern=".."><token/></rule> etc, and empty default rules have children)
	hasChildren := r.Emitter != nil || len(r.Mutators) > 0
	if !hasChildren {
		fmt.Fprintf(b, "      <rule%s/>\n", patAttr)
		return
	}
	fmt.Fprintf(b, "      <rule%s>\n", patAttr)
	if r.Emitter != nil {
		writeEmitterXML(b, r.Emitter, "        ")
	}
	for _, m := range r.Mutators {
		switch m.Kind {
		case "push":
			// produce duplicate state attributes for multiple states
			attrs := ""
			for _, s := range m.States {
				attrs += fmt.Sprintf(" state=\"%s\"", xmlEscape(s))
			}
			fmt.Fprintf(b, "        <push%s/>\n", attrs)
		case "pop":
			fmt.Fprintf(b, "        <pop depth=\"%d\"/>\n", m.Depth)
		case "combined":
			attrs := ""
			for _, s := range m.States {
				attrs += fmt.Sprintf(" state=\"%s\"", xmlEscape(s))
			}
			fmt.Fprintf(b, "        <combined%s/>\n", attrs)
		}
	}
	b.WriteString("      </rule>\n")
}
func writeEmitterXML(b *strings.Builder, e *Emitter, indent string) {
	switch e.Kind {
	case "t":
		fmt.Fprintf(b, "%s<token type=\"%s\"/>\n", indent, string(e.Token))
	case "u":
		fmt.Fprintf(b, "%s<using lexer=\"%s\"/>\n", indent, xmlEscape(e.Lexer))
	case "s":
		fmt.Fprintf(b, "%s<usingself state=\"%s\"/>\n", indent, xmlEscape(e.State))
	case "b":
		fmt.Fprintf(b, "%s<bygroups>\n", indent)
		for _, g := range e.Groups {
			gg := g
			writeEmitterXML(b, &gg, indent+"  ")
		}
		fmt.Fprintf(b, "%s</bygroups>\n", indent)
	case "ubg":
		fmt.Fprintf(b, "%s<usingbygroup>\n", indent)
		fmt.Fprintf(b, "%s  <sublexer_name_group>%d</sublexer_name_group>\n", indent, e.SubNameGroup)
		fmt.Fprintf(b, "%s  <code_group>%d</code_group>\n", indent, e.CodeGroup)
		fmt.Fprintf(b, "%s  <emitters>\n", indent)
		for _, t := range e.UbgTokens {
			fmt.Fprintf(b, "%s    <token type=\"%s\"/>\n", indent, string(t))
		}
		fmt.Fprintf(b, "%s  </emitters>\n", indent)
		fmt.Fprintf(b, "%s</usingbygroup>\n", indent)
	case "unknown":
		fmt.Fprintf(b, "%s<%s/>\n", indent, e.Lexer)
	}
}
EOF
"}

{"command":"cat > main.go <<'EOF'
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"runtime/pprof"
	"strings"
)

var progName string
var profileFile *os.File

func main() {
	initStyles()
	initLexers()
	// pattern winners init after lexers
	initPatternWinners()

	progName = filepath.Base(os.Args[0])
	isLessFilter := progName == ".lessfilter"
	result := parseArgs(os.Args[1:])
	if result.errMsg != "" {
		fmt.Fprintf(os.Stderr, "%s: error: %s\n", progName, result.errMsg)
		os.Exit(80)
	}
	if result.hook == "help" {
		writeHelp(os.Stdout, progName)
		return
	}
	if result.hook == "version" {
		fmt.Fprintln(os.Stdout, "?-?-?")
		return
	}
	cli := result.cli
	if isLessFilter {
		cli.Fail = true
	}
	err := run(cli)
	if err != nil {
		// If err is silent exit, it would have exited already inside run (os.Exit(1))
		fmt.Fprintf(os.Stderr, "%s: error: %s\n", progName, err.Error())
		os.Exit(1)
	}
	// success: stop profile if started
	if profileFile != nil {
		pprof.StopCPUProfile()
		profileFile.Close()
	}
}

func run(cli *CLI) error {
	// XML dump
	if cli.XML != "" {
		return dumpXML(cli.XML)
	}
	if cli.List {
		_, err := io.WriteString(os.Stdout, listData)
		return err
	}
	// Profile
	if cli.Profile != "" {
		f, err := os.Create(cli.Profile)
		if err != nil {
			return err
		}
		profileFile = f
		if err := pprof.StartCPUProfile(f); err != nil {
			// if start fails, (?) under original they'd (?) return? ignore
			_ = err
		}
	}
	// Style
	style, err := loadStyle(cli.Style)
	if err != nil {
		return err
	}
	// Style modifications (Highlight before Lines, in order of error reporting)
	if cli.HTMLHighlightStyle != "" {
		entry, err := parseStyleEntry(cli.HTMLHighlightStyle)
		if err != nil {
			return fmt.Errorf("invalid entry for LineHighlight: %s", err.Error())
		}
		ns, err := style.CloneWith(map[TT]StyleEntry{TTLineHighlight: entry})
		if err != nil {
			return err
		}
		style = ns
	}
	if cli.HTMLLinesStyle != "" {
		entry, err := parseStyleEntry(cli.HTMLLinesStyle)
		if err != nil {
			return fmt.Errorf("invalid entry for LineNumbers: %s", err.Error())
		}
		ns, err := style.CloneWith(map[TT]StyleEntry{TTLineNumbers: entry})
		if err != nil {
			return err
		}
		style = ns
	}
	// Determine formatter selection
	formatterName := cli.Formatter
	isJSON := cli.JSON
	isHTML := cli.HTMLFlag
	isSVG := cli.SVG
	// precedence: json > html > svg > formatter field unnamed? Original order json then html then svg.
	selectedFormatterName := formatterName
	if isJSON {
		selectedFormatterName = "json"
	} else if isHTML {
		selectedFormatterName = "html"
	} else if isSVG {
		selectedFormatterName = "svg"
	}
	isHTMLFormatter := selectedFormatterName == "html"

	// HTMLStyles shortcut
	if cli.HTMLStyles {
		if isHTMLFormatter {
			// Need to parse HTML options (range parsing) before writing CSS because building HTML formatter may fail
			if _, err := parseRanges(cli.HTMLHighlight); err != nil {
				return err
			}
			opts := htmlOptsFromCLI(cli)
			return writeCSS(os.Stdout, style, opts.Prefix, normalisedTabWidth(opts.TabWidth), overridesForStyle(style, opts))
		}
		return writeCSS(os.Stdout, style, "", 8, nil)
	}

	// Build formatter (for HTML, parse ranges early)
	var htmlOpts htmlOptions
	if isHTMLFormatter {
		htmlOpts = htmlOptsFromCLI(cli)
		if _, err := parseRanges(cli.HTMLHighlight); err != nil {
			return err
		}
	}

	// Lexer resolution if explicit
	var explicitLexer *LexerDef
	if cli.Lexer != "autodetect" {
		lx, err := loadLexerExplicit(cli.Lexer)
		if err != nil {
			return err
		}
		explicitLexer = lx
	}

	traceEnabled = cli.Trace

	// If no files, stdin
	if len(cli.Files) == 0 {
		contents, err := io.ReadAll(os.Stdin)
		if err != nil {
			return err
		}
		lexer := explicitLexer
		if lexer == nil {
			// autodetect using filename if provided
			if cli.Filename != "" {
				if ld := matchLexerForFilename(cli.Filename); ld != nil {
					lexer = ld
				}
			}
			if lexer == nil {
				if ld := analyseText(string(contents)); ld != nil {
					lexer = ld
				}
			}
			if lexer == nil {
				lexer = fallbackLexer
			}
		}
		// Fail handling
		if cli.Fail && !cli.Check {
			if len(contents) == 0 {
				return fmt.Errorf("EOF")
			}
			if lexer == fallbackLexer || (lexer != nil && lexer.Name == "fallback") {
				os.Exit(1)
			}
		}
		// Check mode for stdin: original does NOT check, it formats normally
		// So proceed to formatting
		tokens := tokenise(lexer, string(contents))
		return formatToWriter(os.Stdout, tokens, style, selectedFormatterName, htmlOpts)
	}

	// Files mode
	var outWriter io.Writer
	var buf *bytes.Buffer
	var bw *bufio.Writer
	if cli.Unbuffered {
		outWriter = os.Stdout
	} else {
		buf = &bytes.Buffer{}
		bw = bufio.NewWriter(buf)
		outWriter = bw
	}
	for _, filenameAbs := range cli.Files {
		// filenameAbs is absolute (except "-")
		var contents []byte
		var err error
		var displayName string
		if filenameAbs == "-" {
			// open as literal "-"
			f, err := os.Open("-")
			if err != nil {
				return err
			}
			contents, err = io.ReadAll(f)
			f.Close()
			if err != nil {
				return err
			}
			displayName = filenameAbs
		} else {
			contents, err = os.ReadFile(filenameAbs)
			if err != nil {
				return err
			}
			displayName = filenameAbs
		}
		// per-file lexer
		lexer := explicitLexer
		if lexer == nil {
			// match by filename (the file's absolute path)
			if ld := matchLexerForFilename(displayName); ld != nil {
				lexer = ld
			}
			if lexer == nil {
				if ld := analyseText(string(contents)); ld != nil {
					lexer = ld
				}
			}
			if lexer == nil {
				lexer = fallbackLexer
			}
		}
		// Fail handling (before check check? check ignores fail)
		if cli.Fail && !cli.Check {
			if len(contents) == 0 {
				return fmt.Errorf("EOF")
			}
			if lexer == fallbackLexer || (lexer != nil && lexer.Name == "fallback") {
				// do not flush buffered output
				os.Exit(1)
			}
		}
		if cli.Check {
			// tokenise and report errors
			tokens := tokenise(lexer, string(contents))
			// Compute line/col per token start: need reconstruct positions: tokens are coalesced, we can sum values sequentially
			line := 1
			col := 0
			// col count in what units? earlier findings: col is byte/rune? Let's use rune count resetting on newline, counting each rune, initial 0.
			// tokens values contain newlines; iterating chars of previous tokens updates line/col.
			for _, tok := range tokens {
				if tok.Type == "Error" {
					fmt.Fprintf(outWriter, "%s:%d:%d %q\n", displayName, line, col, tok.Value)
				}
				// advance line/col over tok.Value
				for _, r := range tok.Value {
					if r == '\n' {
						line++
						col = 0
					} else {
						col++
					}
				}
			}
			continue
		}
		tokens := tokenise(lexer, string(contents))
		if err := formatToWriter(outWriter, tokens, style, selectedFormatterName, htmlOpts); err != nil {
			return err
		}
	}
	if bw != nil {
		if err := bw.Flush(); err != nil {
			return err
		}
		// write buffer to stdout
		if _, err := os.Stdout.Write(buf.Bytes()); err != nil {
			return err
		}
	}
	return nil
}

func htmlOptsFromCLI(cli *CLI) htmlOptions {
	return htmlOptions{
		Prefix: cli.HTMLPrefix,
		TabWidth: cli.HTMLTabWidth,
		Inline: cli.HTMLInlineStyles,
		Only: cli.HTMLOnly,
		PreventPre: cli.HTMLPreventSurroundingPre,
		Lines: cli.HTMLLines,
		LinesTable: cli.HTMLLinesTable,
		LinesStyle: cli.HTMLLinesStyle,
		HighlightStr: cli.HTMLHighlight,
		HighlightStyle: cli.HTMLHighlightStyle,
		BaseLine: cli.HTMLBaseLine,
		Linkable: cli.HTMLLinkableLines,
		AllStyles: cli.HTMLAllStyles,
	}
}

func formatToWriter(w io.Writer, tokens []Token, style *Style, formatterName string, htmlOpts htmlOptions) error {
	switch formatterName {
	case "noop":
		return formatNoop(w, tokens)
	case "tokens":
		return formatTokens(w, tokens)
	case "json":
		return formatJSON(w, tokens)
	case "terminal", "terminal8", "terminal16", "terminal256", "terminal16m":
		return formatTerminal(w, tokens, style, formatterName)
	case "html":
		return formatHTML(w, tokens, style, htmlOpts)
	case "svg":
		return formatSVG(w, tokens, style)
	default:
		return formatTerminal(w, tokens, style, formatterName)
	}
}

func loadStyle(name string) (*Style, error) {
	if st := getBuiltinStyle(name); st != nil {
		return st, nil
	}
	// load file
	f, err := os.Open(name)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	data, err := io.ReadAll(f)
	if err != nil {
		return nil, err
	}
	// Style XML loader expects Reader; emulate EOF if file empty/not xml via loader
	return loadStyleXML(data)
}

func loadLexerExplicit(name string) (*LexerDef, error) {
	if ld := lexersGet(name); ld != nil {
		return ld, nil
	}
	// try file
	// Determine if file exists (normal path)
	abs, _ := filepath.Abs(name)
	info, err := os.Stat(abs)
	if err != nil {
		// not exist -> fallback
		return fallbackLexer, nil
	}
	// compute rel to cwd
	cwd, _ := os.Getwd()
	rel, err := filepath.Rel(cwd, abs)
	if err != nil {
		rel = name
	}
	if rel == ".." || strings.HasPrefix(rel, "../") || strings.HasPrefix(rel, ".."+string(os.PathSeparator)) {
		return nil, fmt.Errorf("open %s: invalid argument", filepath.ToSlash(rel))
	}
	if info.IsDir() {
		return nil, fmt.Errorf("read ./%s: is a directory", filepath.ToSlash(rel))
	}
	data, err := os.ReadFile(abs)
	if err != nil {
		return nil, err
	}
	source := filepath.ToSlash(rel)
	ld, err := loadLexerXML(data, source)
	if err != nil {
		return nil, err
	}
	return ld, nil
}
EOF
"}

