{"command":"cat > pattern_matcher.go <<'EOF'
package main

import (
	"regexp"
	"strings"
)

type Assertion struct {
	Kind string // aheadPos, aheadNeg, behindPos, behindNeg
	Pattern string
	Re *regexp.Regexp // for ahead: anchored regex ; for behind: regex to match suffix
}

type PatternMatcher struct {
	Re *regexp.Regexp
	Pre []Assertion
	Post []Assertion
	CorePattern string
	Flags map[string]bool
	StartsWithCaret bool
}

func compileAssertion(kind, pat string, flags map[string]bool) Assertion {
	a := Assertion{Kind: kind, Pattern: pat}
	// compile the assertion subpattern using trivial handling (strip inner lookarounds)
	p := removeLookAssertions(pat)
	p = removePossessive(p)
	// replace backrefs approx
	p = replaceBackrefs(p)
	if kind == "aheadPos" || kind == "aheadNeg" {
		re, err := regexp.Compile(wrapPattern(p, flags))
		if err == nil { a.Re = re }
	} else {
		// behind: need to match suffix ending at pos: compile with (?:pat)\z on prefix text
		// Use flags but ensure multiline? Use wrap but replace wrapper: we build custom: "(?m)(?:pat)\\z" plus flag handling similar
		// Simplest: use wrapPattern to get flags, then add \z inside? Wrap pattern returns "(?m)(?:p)" - we need "(?m)(?:p)\\z"
		base := wrapPattern(p, flags)
		// base is "(?flags)(?:p)" - insert \z before final )
		// It ends with ")" for the group; append \z after? "(?m)(?:p)\z" is correct if we close group then \z
		re, err := regexp.Compile(base + `\z`)
		if err == nil { a.Re = re } else {
			// fallback
			re2, err2 := regexp.Compile(`(?:` + p + `)\z`)
			if err2 == nil { a.Re = re2 }
		}
	}
	return a
}
func replaceBackrefs(p string) string {
	var out strings.Builder
	for i := 0; i < len(p); i++ {
		if p[i] == '\\' && i+1 < len(p) && p[i+1] >= '1' && p[i+1] <= '9' {
			out.WriteString("(?:.*?)")
			i++
			continue
		}
		out.WriteByte(p[i])
	}
	return out.String()
}

func checkAssertion(a Assertion, text string, pos int) bool {
	switch a.Kind {
	case "aheadPos":
		if a.Re == nil { return true }
		loc := a.Re.FindStringIndex(text[pos:])
		if loc != nil && loc[0] == 0 { return true }
		return false
	case "aheadNeg":
		if a.Re == nil { return true }
		loc := a.Re.FindStringIndex(text[pos:])
		if loc != nil && loc[0] == 0 { return false }
		return true
	case "behindPos":
		if a.Re == nil { return true }
		// Need to allow match that ends at pos; our re has \z at end of prefix string
		loc := a.Re.FindStringIndex(text[:pos])
		if loc != nil && loc[1] == pos { return true }
		// FindStringIndex finds earliest match ending at pos? It finds earliest starting; if any match ends at pos, the regex with \z forces end.
		return false
	case "behindNeg":
		if a.Re == nil { return true }
		loc := a.Re.FindStringIndex(text[:pos])
		if loc != nil && loc[1] == pos { return false }
		return true
	}
	return true
}

// extractAssertions processes pattern and returns matcher
func makePatternMatcher(pat string, flags map[string]bool) (*PatternMatcher, error) {
	pm := &PatternMatcher{Flags: flags}
	core := pat
	// Extract prefix assertions: scan pattern sequentially
	var pre []Assertion
	i := 0
	// skip leading zero-width tokens, collecting assertions
	for i < len(core) {
		rest := core[i:]
		// flag group (?i) (?i:...) etc - if its a flag directive "(?i)" or "(?i-m)" etc (ending with ) and containing only flags) keep and advance
		// lookahead/behind
		if strings.HasPrefix(rest, "(?=") || strings.HasPrefix(rest, "(?!") {
			kind := "aheadPos"; prefixLen := 3
			if rest[2] == '!' { kind = "aheadNeg" }
			end := findMatchingParen(core, i)
			if end == -1 { break }
			inner := core[i+prefixLen : end]
			pre = append(pre, compileAssertion(kind, inner, flags))
			i = end + 1
			continue
		}
		if strings.HasPrefix(rest, "(?<=") || strings.HasPrefix(rest, "(?<!") {
			kind := "behindPos"; prefixLen := 4
			if rest[3] == '!' { kind = "behindNeg" }
			end := findMatchingParen(core, i)
			if end == -1 { break }
			inner := core[i+prefixLen : end]
			pre = append(pre, compileAssertion(kind, inner, flags))
			i = end + 1
			continue
		}
		// zero-width tokens: ^, \b, \B, \A, \z, $
		if rest[0] == '^' || rest[0] == '$' {
			i++
			continue
		}
		if strings.HasPrefix(rest, `\b`) || strings.HasPrefix(rest, `\B`) || strings.HasPrefix(rest, `\A`) {
			i += 2
			continue
		}
		if strings.HasPrefix(rest, "(?") {
			// flag group like (?i) - if it closes quickly and content is flags, skip as zero width but keep in core for scope
			end := findMatchingParen(core, i)
			if end != -1 {
				content := core[i+2 : end]
				// if content consists of flag letters and - and :? If colon, it's a group (consuming), break
				if strings.Contains(content, ":") {
					break
				}
				// flag directive
				i = end + 1
				continue
			}
			break
		}
		break
	}
	if len(pre) > 0 {
		// reconstruct core without the extracted prefix assertions, but keep other prefix tokens ( ^ etc)
		// Our scanning above advanced i over zero-width tokens and assertions; but if we simply remove assertions substring by substring earlier, it's easier: rebuild by removing assertion substrings from original while preserving other characters.
		core = removePrefixAssertions(pat)
	}
	pm.Pre = pre
	// Extract trailing assertions (post)
	var post []Assertion
	for {
		trimmedCore, assertion, ok := extractTrailingAssertion(core, flags)
		if !ok { break }
		post = append([]Assertion{assertion}, post...)
		core = trimmedCore
	}
	pm.Post = post
	// Remove remaining internal assertions (ignore) and backrefs/possessive
	core = removeLookAssertions(core)
	core = removePossessive(core)
	core = replaceBackrefs(core)
	pm.CorePattern = core
	if strings.HasPrefix(strings.TrimLeft(core, "(?"), "^") || strings.HasPrefix(core, "^") {
		pm.StartsWithCaret = true
	}
	reStr := wrapPattern(core, flags)
	re, err := regexp.Compile(reStr)
	if err != nil {
		return nil, err
	}
	pm.Re = re
	return pm, nil
}

func removePrefixAssertions(pat string) string {
	var out strings.Builder
	i := 0
	// only remove assertions in prefix phase: keep scanning until first consuming token
	seenConsuming := false
	for i < len(pat) {
		if seenConsuming {
			out.WriteString(pat[i:])
			break
		}
		rest := pat[i:]
		if strings.HasPrefix(rest, "(?=") || strings.HasPrefix(rest, "(?!") {
			end := findMatchingParen(pat, i)
			if end == -1 { break }
			i = end + 1
			continue
		}
		if strings.HasPrefix(rest, "(?<=") || strings.HasPrefix(rest, "(?<!") {
			end := findMatchingParen(pat, i)
			if end == -1 { break }
			i = end + 1
			continue
		}
		// determine if this is consuming: look at char
		c := pat[i]
		if c == '^' || c == '$' {
			out.WriteByte(c); i++; continue
		}
		if c == '\\' && i+1 < len(pat) && (pat[i+1] == 'b' || pat[i+1] == 'B' || pat[i+1] == 'A') {
			out.WriteString(pat[i:i+2]); i+=2; continue
		}
		if strings.HasPrefix(rest, "(?") {
			end := findMatchingParen(pat, i)
			if end != -1 {
				content := pat[i+2:end]
				if !strings.Contains(content, ":") {
					// flag directive consuming zero
					out.WriteString(pat[i:end+1]); i=end+1; continue
				}
			}
		}
		// consuming token reached, copy rest
		seenConsuming = true
		out.WriteString(pat[i:])
		break
	}
	return out.String()
}

func extractTrailingAssertion(pat string, flags map[string]bool) (string, Assertion, bool) {
	// find top-level assertions at end: need to parse atoms from start to find last atom start
	type atom struct { start, end int; kind string; inner string }
	var atoms []atom
	i := 0
	inClass := false
	esc := false
	// Instead, scan and record positions of top-level groups starting with (?= etc that end at len-1
	// Simplistic scanning: iterate i, when we encounter '(' at depth0 start, record its start and find its end.
	depth := 0
	lastLookStart := -1
	lastLookEnd := -1
	var lastKind string
	var lastInner string
	for idx := 0; idx < len(pat); idx++ {
		c := pat[idx]
		if esc { esc = false; continue }
		if c == '\\' { esc = true; continue }
		if inClass {
			if c == ']' { inClass = false }
			continue
		}
		if c == '[' { inClass = true; continue }
		if c == '(' {
			if depth == 0 {
				if strings.HasPrefix(pat[idx:], "(?=") || strings.HasPrefix(pat[idx:], "(?!") || strings.HasPrefix(pat[idx:], "(?<=") || strings.HasPrefix(pat[idx:], "(?<!") {
					end := findMatchingParen(pat, idx)
					if end == len(pat)-1 {
						// candidate trailing
						lastLookStart = idx; lastLookEnd = end
						if strings.HasPrefix(pat[idx:], "(?=") { lastKind="aheadPos"; lastInner=pat[idx+3:end] } else if strings.HasPrefix(pat[idx:], "(?!") { lastKind="aheadNeg"; lastInner=pat[idx+3:end] } else if strings.HasPrefix(pat[idx:], "(?<=") { lastKind="behindPos"; lastInner=pat[idx+4:end] } else { lastKind="behindNeg"; lastInner=pat[idx+4:end] }
					}
				}
			}
			depth++
			continue
		}
		if c == ')' {
			depth--
			continue
		}
	}
	if lastLookStart != -1 && lastLookEnd == len(pat)-1 {
		core := pat[:lastLookStart]
		a := compileAssertion(lastKind, lastInner, flags)
		return core, a, true
	}
	_ = atoms
	_ = i
	return pat, Assertion{}, false
}

func (pm *PatternMatcher) MatchAt(text string, pos int) ([][]int, int, bool) {
	// caret check
	if pm.StartsWithCaret {
		if pos > 0 && text[pos-1] != '\n' {
			// pattern beginning with ^ cannot match mid-line
			// Note: if core pattern's ^ is inside alternative, this may be too strict, but patterns handled are primary ^ ones
			return nil, pos, false
		}
	}
	for _, a := range pm.Pre {
		if !checkAssertion(a, text, pos) {
			return nil, pos, false
		}
	}
	if pm.Re == nil {
		return nil, pos, false
	}
	loc := pm.Re.FindStringSubmatchIndex(text[pos:])
	if loc == nil || loc[0] != 0 {
		return nil, pos, false
	}
	end := pos + loc[1]
	for _, a := range pm.Post {
		if !checkAssertion(a, text, end) {
			return nil, pos, false
		}
	}
	groups := pairsFromLoc(loc, pos)
	return groups, end, true
}
EOF
"}

