	case "^m": return pos==0 || (pos>0 && text[pos-1]=='\n')
	case "$": return pos==len(text)
	case "$m": return pos==len(text) || (pos < len(text) && text[pos]=='\n')
	case "A": return pos==0
	case "z": return pos==len(text)
	case "Z": return pos==len(text) || (pos==len(text)-1 && text[pos]=='\n')
	case "G": return true // matcher is anchored externally
	case "b":
		left:=pos>0 && isWordRune(text[pos-1]); right:=pos < len(text) && isWordRune(text[pos]); return left!=right
	case "B":
		left:=pos>0 && isWordRune(text[pos-1]); right:=pos < len(text) && isWordRune(text[pos]); return left==right
	}
	return false
