func (m *btMatcher) matchSeq(nodes []btNode, idx int, pos int, caps [][]int, cont btCont) bool {
	if idx>=len(nodes){ return cont(pos,caps)}
	return m.matchNode(nodes[idx],pos,caps, func(np int, nc [][]int) bool { return m.matchSeq(nodes,idx+1,np,nc,cont)})
}
func (m *btMatcher) matchRepeat(n btRepeat, pos int, caps [][]int, count int, cont btCont) bool {
	// greedy vs lazy
	canMore := n.max==-1 || count < n.max
	if n.greedy {
		if canMore {
			// try one more, but avoid zero-length infinite
			ok:=m.matchNode(n.node,pos,caps, func(np int, nc [][]int) bool {
				if np==pos {
					// zero length repetition: don't loop
					if count+1>=n.min { return cont(np,nc)}; return false
				}
				return m.matchRepeat(n,np,nc,count+1,cont)
			})
			if ok { return true }
		}
		if count>=n.min { return cont(pos,caps)}
		return false
	} else {
		if count>=n.min {
			if cont(pos,caps){ return true }
		}
		if canMore {
			return m.matchNode(n.node,pos,caps, func(np int, nc [][]int) bool {
				if np==pos { return false }
				return m.matchRepeat(n,np,nc,count+1,cont)
			})
		}
		return false
	}
}

// Custom match entry: text runes, pos rune index, returns end rune index, caps (rune indices), ok
func btMatch(pattern string, lexerFlags map[string]bool, text []rune, pos int) (int, [][]int, bool) {
	parser:=&btParser{s:[]rune(pattern), lexerFlags:lexerFlags}
	node, err:=parser.parse()
	if err!=nil{ return pos,nil,false }
	matcher:=&btMatcher{text:text, maxSteps:200000}
	caps:=make([][]int, parser.captureCount+1)
	for i:=range caps{caps[i]=[]int{-1,-1}}
	caps[0]=[]int{pos,pos}
	var finalPos int; var finalCaps [][]int; ok:=false
	success:=matcher.matchNode(node,pos,caps, func(np int, nc [][]int) bool { finalPos=np; finalCaps=nc; ok=true; return true })
	if !success || !ok { return pos,nil,false }
	if len(finalCaps)==0{finalCaps=caps}
	finalCaps[0]=[]int{pos,finalPos}
	// ensure all groups present
	for len(finalCaps) < parser.captureCount+1 { finalCaps=append(finalCaps, []int{-1,-1})}
	return finalPos, finalCaps, true
}

