import pathlib
p=pathlib.Path("pattern_matcher.go"); t=p.read_text()
# extend backref detection to lazy+lookahead
old="""	// Backreference patterns use custom engine
	if hasBackref(pat) {
		pm.UseBT = true
		// still compile a fallback regex for safety
	}"""
new="""	// Backreference patterns use custom engine
	if hasBackref(pat) || hasLazyWithLookahead(pat) {
		pm.UseBT = true
		// still compile a fallback regex for safety
	}"""
t=t.replace(old,new)
# add helper function at end
t += '''
func hasLazyWithLookahead(pat string) bool {
    inClass:=false; esc:=false
    lazyPos:=-1
    for i:=0;i<len(pat);i++ {
        c:=pat[i]
        if esc { esc=false; continue }
        if c=='\\\\' { esc=true; continue }
        if inClass { if c==']' {inClass=false}; continue }
        if c=='[' {inClass=true; continue}
        if (c=='*'||c=='+'||c=='?'||c=='}') && i+1<len(pat) && pat[i+1]=='?' {
            // lazy quantifier, not possessive?? following char is '?' - could be part of (?: no, lazy quantifier char is second ?
            lazyPos=i
        }
        if lazyPos>=0 && c=='(' && i+2<len(pat) && pat[i+1]=='?' && (pat[i+2]=='='||pat[i+2]=='!') {
            return true
        }
    }
    return false
}
'''
p.write_text(t)
